import { useMemo, useState } from 'react';
import ReactECharts from 'echarts-for-react';
import type { EChartsOption } from 'echarts';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Tabs, TabsList, TabsTrigger } from '@/components/ui/tabs';
import {
  TrendingUp,
  Zap,
  Target,
  Lightbulb,
  AlertTriangle,
  CalendarClock,
} from 'lucide-react';
import { cn } from '@/lib/utils';
import { type PurchaseOrder, type LeadTimeTrendItem, type LeadTimeSuggestion } from './types';

const CHART_COLORS = {
  avg: '#5D8A72',
  count: '#C9A87C',
};

function calcLeadDays(orderedAt: string, arrivedAt: string): number | null {
  if (!orderedAt || !arrivedAt) return null;
  const start = new Date(orderedAt).getTime();
  const end = new Date(arrivedAt).getTime();
  if (isNaN(start) || isNaN(end) || end <= start) return null;
  return Math.round(((end - start) / (1000 * 60 * 60 * 24)) * 10) / 10;
}

function toDateStr(s: string): string {
  if (!s) return '';
  const d = new Date(s);
  if (isNaN(d.getTime())) return s.slice(0, 10);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function calcTrend(orders: PurchaseOrder[], days: number): LeadTimeTrendItem[] {
  const now = new Date();
  const dateList: string[] = [];
  for (let i = days - 1; i >= 0; i--) {
    const d = new Date(now);
    d.setDate(now.getDate() - i);
    const pad = (n: number) => String(n).padStart(2, '0');
    dateList.push(`${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`);
  }

  // 只要有到货时间就计入到货单量；purchaseTime为空的不算时效但单量要算
  const arrivedOrders = orders.filter((o) => {
    const isArrived = o.status === 'arrived' || o.status === 'warehoused' || !!o.arrivedAt;
    return isArrived && !!o.arrivedAt;
  });

  return dateList.map((date) => {
    const dayItems = arrivedOrders.filter((o) => toDateStr(o.arrivedAt!) === date);
    const count = dayItems.length;
    if (count === 0) return { date, avgDays: null, count: 0 };
    const validItems = dayItems.filter((o) => o.purchaseTime || o.purchaseDate);
    if (validItems.length === 0) return { date, avgDays: null, count };
    const totalDays = validItems.reduce((sum, o) => {
      const startStr = o.purchaseTime || o.purchaseDate || '';
      const d = calcLeadDays(startStr, o.arrivedAt!);
      return sum + (d ?? 0);
    }, 0);
    return {
      date,
      avgDays: Math.round((totalDays / validItems.length) * 10) / 10,
      count,
    };
  });
}

function generateSuggestions(orders: PurchaseOrder[]): LeadTimeSuggestion[] {
  const result: LeadTimeSuggestion[] = [];

  const arrivedOrders = orders.filter((o) => {
    const isArrived = o.status === 'arrived' || o.status === 'warehoused' || !!o.arrivedAt;
    const hasPurchase = o.purchaseTime || o.purchaseDate;
    const hasArrival = !!o.arrivedAt;
    return isArrived && hasPurchase && hasArrival;
  });

  if (arrivedOrders.length === 0) {
    const orderedCount = orders.length;
    if (orderedCount > 0) {
      result.push({
        type: 'info',
        icon: 'trending-up',
        title: `共 ${orderedCount} 条在途订单`,
        content: '当前有国内采购订单正在运输途中，首单到货后将自动生成时效趋势分析与优化建议。建议关注运输超7天未到货的订单，及时跟进物流状态。',
      });
    }
    return result;
  }

  const totalDays = arrivedOrders.reduce((sum, o) => {
    const startStr = o.purchaseTime || o.purchaseDate || '';
    const d = calcLeadDays(startStr, o.arrivedAt!);
    return sum + (d ?? 0);
  }, 0);
  const avgDays = Math.round((totalDays / arrivedOrders.length) * 10) / 10;

  if (avgDays > 7) {
    result.push({
      type: 'warning',
      icon: 'trending-up',
      title: `平均时效偏长（${avgDays}天）`,
      content: '国内采购平均时效超过7天，建议关注供应商发货速度与物流渠道效率，可考虑更换更快的快递或与供应商协商缩短发货周期。',
    });
  } else if (avgDays > 4) {
    result.push({
      type: 'info',
      icon: 'lightbulb',
      title: `平均时效 ${avgDays} 天`,
      content: '时效处于正常偏高水平，建议持续监控核心供应商表现，旺季前提前备货以应对可能的延误。',
    });
  } else {
    result.push({
      type: 'success',
      icon: 'zap',
      title: `时效良好（平均${avgDays}天）`,
      content: '当前国内采购时效表现优秀，建议保持现有供应商和物流渠道合作，并可尝试将优秀渠道的经验复制到其他品类。',
    });
  }

  // 近7天 vs 上周对比
  const now = Date.now();
  const weekAgo = now - 7 * 24 * 3600 * 1000;
  const twoWeeksAgo = now - 14 * 24 * 3600 * 1000;

  const items = arrivedOrders.map((o) => ({
    orderedAt: o.purchaseTime || o.purchaseDate || '',
    arrivedAt: o.arrivedAt || '',
  }));

  const lastWeekItems = items.filter((i) => new Date(i.arrivedAt).getTime() >= weekAgo);
  const prevWeekItems = items.filter(
    (i) => new Date(i.arrivedAt).getTime() >= twoWeeksAgo && new Date(i.arrivedAt).getTime() < weekAgo,
  );

  if (lastWeekItems.length > 0 && prevWeekItems.length > 0) {
    const lastAvg =
      lastWeekItems.reduce((s, i) => s + (calcLeadDays(i.orderedAt, i.arrivedAt) ?? 0), 0) / lastWeekItems.length;
    const prevAvg =
      prevWeekItems.reduce((s, i) => s + (calcLeadDays(i.orderedAt, i.arrivedAt) ?? 0), 0) / prevWeekItems.length;
    const diff = Math.round((lastAvg - prevAvg) * 10) / 10;
    if (diff < -0.5) {
      result.push({
        type: 'success',
        icon: 'trending-down',
        title: `近7天时效加快 ${Math.abs(diff)} 天`,
        content: `相比上周，近7天平均时效从 ${Math.round(prevAvg * 10) / 10} 天缩短至 ${Math.round(lastAvg * 10) / 10} 天，采购效率有所提升。`,
      });
    } else if (diff > 0.5) {
      result.push({
        type: 'warning',
        icon: 'trending-up',
        title: `近7天时效变慢 ${diff} 天`,
        content: `相比上周，近7天平均时效从 ${Math.round(prevAvg * 10) / 10} 天增加到 ${Math.round(lastAvg * 10) / 10} 天，建议排查是否有供应商发货延迟或快递爆仓。`,
      });
    }
  }

  result.push({
    type: 'info',
    icon: 'target',
    title: `累计到货 ${arrivedOrders.length} 单`,
    content: `国内采购已到货 ${arrivedOrders.length} 条，数据持续积累后趋势分析会更准确。`,
  });

  return result;
}

export default function DomesticLeadTimeSection({ orders }: { orders: PurchaseOrder[] }) {
  const [chartView, setChartView] = useState<'7d' | '30d'>('7d');

  const trendData = useMemo(() => calcTrend(orders, chartView === '7d' ? 7 : 30), [orders, chartView]);
  const suggestions = useMemo(() => generateSuggestions(orders), [orders]);

  const chartOption = useMemo<EChartsOption>(
    () => ({
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'cross' },
      },
      legend: { bottom: 0, type: 'scroll' },
      grid: { left: '3%', right: '4%', bottom: '18%', containLabel: true },
      xAxis: {
        type: 'category',
        boundaryGap: true,
        data: trendData.map((d) => d.date.slice(5)),
        axisLabel: { fontSize: 10 },
      },
      yAxis: [
        {
          type: 'value',
          name: '时效(天)',
          position: 'left',
          axisLabel: { fontSize: 10 },
          splitLine: { lineStyle: { type: 'dashed', opacity: 0.5 } },
          minInterval: 1,
        },
        {
          type: 'value',
          name: '到货单数',
          position: 'right',
          axisLabel: { fontSize: 10 },
          splitLine: { show: false },
          minInterval: 1,
        },
      ],
      series: [
        {
          name: '平均时效',
          type: 'line',
          yAxisIndex: 0,
          smooth: true,
          data: trendData.map((d) => d.avgDays),
          lineStyle: { color: CHART_COLORS.avg, width: 2 },
          itemStyle: { color: CHART_COLORS.avg },
          connectNulls: true,
        },
        {
          name: '到货单数',
          type: 'bar',
          yAxisIndex: 1,
          data: trendData.map((d) => d.count),
          itemStyle: { color: CHART_COLORS.count, borderRadius: [4, 4, 0, 0] },
          barWidth: 12,
        },
      ],
    }),
    [trendData],
  );

  void CalendarClock;
  void AlertTriangle;

  const iconMap: Record<string, typeof TrendingUp> = {
    'trending-up': TrendingUp,
    'trending-down': TrendingUp,
    zap: Zap,
    target: Target,
    lightbulb: Lightbulb,
  };

  const colorMap: Record<string, string> = {
    warning: 'text-amber-500 bg-amber-50',
    info: 'text-blue-500 bg-blue-50',
    success: 'text-emerald-500 bg-emerald-50',
  };

  return (
    <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
      <Card className="lg:col-span-2">
        <CardHeader className="pb-2 flex-row items-center justify-between">
          <CardTitle className="text-base flex items-center gap-2">
            <TrendingUp className="size-4 text-primary" />
            采购时效趋势
          </CardTitle>
          <Tabs value={chartView} onValueChange={(v) => setChartView(v as '7d' | '30d')}>
            <TabsList className="h-7">
              <TabsTrigger value="7d" className="text-xs h-6 px-3">近7天</TabsTrigger>
              <TabsTrigger value="30d" className="text-xs h-6 px-3">近30天</TabsTrigger>
            </TabsList>
          </Tabs>
        </CardHeader>
        <CardContent>
          <ReactECharts
            option={chartOption}
            theme="ud"
            className="h-[280px] w-full"
            notMerge
            lazyUpdate
          />
        </CardContent>
      </Card>

      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base flex items-center gap-2">
            <Lightbulb className="size-4 text-amber-500" />
            时效建议
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-3">
          {suggestions.length === 0 ? (
            <p className="text-sm text-muted-foreground">
              有到货记录后自动生成时效分析建议
            </p>
          ) : (
            suggestions.map((s, i) => {
              const Icon = iconMap[s.icon] || Lightbulb;
              return (
                <div key={i} className="p-3 rounded-lg border border-border/40">
                  <div className="flex items-center gap-2 mb-1.5">
                    <div className={cn('size-7 rounded-md flex items-center justify-center', colorMap[s.type] || colorMap.info)}>
                      <Icon className="size-3.5" />
                    </div>
                    <span className="font-medium text-sm">{s.title}</span>
                  </div>
                  <p className="text-xs text-muted-foreground leading-relaxed">{s.content}</p>
                </div>
              );
            })
          )}
        </CardContent>
      </Card>
    </div>
  );
}
