import { useState, useEffect, useCallback, useRef, useMemo } from 'react';
import { useOutletContext } from 'react-router-dom';
import { Tabs, TabsList, TabsTrigger, TabsContent } from '@/components/ui/tabs';
import { toast } from 'sonner';
import { logger, scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { useSharedData } from '@/hooks/useSharedData';
 import StatsCards from './StatsCards';
 import OrderToolbar from './OrderToolbar';
 import OrderList from './OrderList';
 import OrderFormDialog from './OrderFormDialog';
 import OrderDetailDrawer from './OrderDetailDrawer';
 import AbnormalSection from './AbnormalSection';
 import DomesticLeadTimeSection from './DomesticLeadTimeSection';
 import LeadTimeSection from './LeadTimeSection';
 import LogisticsDialog from './LogisticsDialog';
 import {
    type PurchaseOrder,
    type LeadTimeRecord,
    type AbnormalRecord,
    type OrderStatus,
    COMMON_SHOPS_KEY,
  } from './types';
 import {
    loadOrders,
    saveOrders,
    loadLeadTimeRecords,
    saveLeadTimeRecords,
    loadKuaidi100Key,
    saveKuaidi100Key,
    detectDomesticAbnormalRecords,
    detectCrossBorderAbnormalRecords,
    computeStats,
    computeMonthlyAmount,
    nextStatus,
    loadCommonShops,
    saveCommonShops,
  } from './utils';

interface OutletContext {
  activeTab?: string;
  setActiveTab?: (tab: string) => void;
}

export default function PurchaseOrderPage() {
  const ctx = useOutletContext<OutletContext>();
  const { pushModule, lastSyncAt } = useSharedData();

    // 订单数据
    const [orders, setOrders] = useState<PurchaseOrder[]>([]);
    const [leadtimeRecords, setLeadtimeRecords] = useState<LeadTimeRecord[]>([]);
    const [kuaidi100Key, setKuaidi100Key] = useState<string>('');
    const [loaded, setLoaded] = useState(false);

  // 主 tab
  const [activeTab, setActiveTab] = useState<'orders' | 'leadtime'>('orders');

  // 订单工具状态
  const [searchKeyword, setSearchKeyword] = useState('');
  const [filterPlatform, setFilterPlatform] = useState('all');
  const [filterStatus, setFilterStatus] = useState('all');
  const [filterShop, setFilterShop] = useState('all');

  // 订单弹窗/抽屉
  const [formOpen, setFormOpen] = useState(false);
  const [editingOrder, setEditingOrder] = useState<PurchaseOrder | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [detailOrder, setDetailOrder] = useState<PurchaseOrder | null>(null);

  // 物流查询
  const [logisticsOpen, setLogisticsOpen] = useState(false);
  const [logisticsTrackingNumber, setLogisticsTrackingNumber] = useState('');
  const [logisticsCarrier, setLogisticsCarrier] = useState('');

  const abnormalSectionRef = useRef<HTMLDivElement>(null);

   // 初始化加载 + 云同步后重新加载
   useEffect(() => {
      try {
        const o = loadOrders();
        const l = loadLeadTimeRecords();
        const k = loadKuaidi100Key();
        setOrders(o);
        setLeadtimeRecords(l);
        setKuaidi100Key(k);
      } catch (err) {
       logger.error('采购模块加载数据失败:', String(err));
     } finally {
       setLoaded(true);
     }
   }, [lastSyncAt]);

  // 共享数据推送防抖
  const pushTimerRef = useRef<number | null>(null);
  const schedulePush = useCallback(() => {
    if (!pushModule) return;
    if (pushTimerRef.current) {
      window.clearTimeout(pushTimerRef.current);
    }
    pushTimerRef.current = window.setTimeout(() => {
      try {
        // 共享订单数据（snake_case 字段）
        const snakeOrders = orders.map((o) => ({
          id: o.id,
          platform: o.platform,
          status: o.status,
          purchase_date: o.purchaseTime || o.purchaseDate || o.createdAt,
          shop: o.shop,
          product_name: o.productName,
          quantity: o.quantity,
          amount: o.amount,
          carrier: o.carrier,
          tracking_number: o.trackingNumber,
          tracking_url: o.trackingUrl,
          remark: o.remark,
          arrival_quality: o.arrivalQuality,
          quality_note: o.qualityNote,
          created_at: o.createdAt,
          updated_at: o.updatedAt,
          arrived_at: o.arrivedAt,
          shipped_at: o.shippedAt,
          warehoused_at: o.warehousedAt,
        }));
        pushModule('purchaseOrders', snakeOrders);

        const snakeLeadtime = leadtimeRecords.map((r) => ({
          id: r.id,
          platform: r.platform,
          status: r.status,
          ordered_at: r.orderedAt,
          arrived_at: r.arrivedAt,
          warehoused_at: r.warehousedAt,
          shop: r.shop,
          product_name: r.productName,
          sale_price: r.salePrice,
          quantity: r.quantity,
          carrier: r.carrier,
          tracking_number: r.trackingNumber,
          arrival_quality: r.arrivalQuality,
          remark: r.remark,
          created_at: r.createdAt,
          updated_at: r.updatedAt,
        }));
        pushModule('leadTimeRecords', snakeLeadtime);
      } catch (err) {
        logger.error('推送采购共享数据失败:', String(err));
      }
    }, 500);
  }, [orders, leadtimeRecords, pushModule]);

  // 订单变动 → 存 localStorage + 推送
  useEffect(() => {
    if (!loaded) return;
    try {
      saveOrders(orders);
      schedulePush();
      flashSaved();
    } catch (err) {
      logger.error('保存采购订单失败:', String(err));
    }
  }, [orders, loaded, schedulePush]);

  useEffect(() => {
    if (!loaded) return;
    try {
      saveLeadTimeRecords(leadtimeRecords);
      schedulePush();
      flashSaved();
    } catch (err) {
      logger.error('保存时效记录失败:', String(err));
    }
   }, [leadtimeRecords, loaded, schedulePush]);

   useEffect(() => {
    if (!loaded) return;
    try {
      saveKuaidi100Key(kuaidi100Key);
    } catch (err) {
      logger.error('保存快递100 key失败:', String(err));
    }
  }, [kuaidi100Key, loaded]);

  // 常用店铺
  const [commonShops, setCommonShops] = useState<string[]>([]);
  useEffect(() => {
    try {
      setCommonShops(loadCommonShops());
    } catch {
      /* ignore */
    }
  }, []);

  // 异常记录（国内 + 跨境分开，总数仍合并用于顶部卡片）
  const domesticAbnormalRecords: AbnormalRecord[] = useMemo(
    () => detectDomesticAbnormalRecords(orders),
    [orders],
  );
  const crossBorderAbnormalRecords: AbnormalRecord[] = useMemo(
    () => detectCrossBorderAbnormalRecords(leadtimeRecords),
    [leadtimeRecords],
  );
  const abnormalRecords: AbnormalRecord[] = useMemo(
    () => [...domesticAbnormalRecords, ...crossBorderAbnormalRecords],
    [domesticAbnormalRecords, crossBorderAbnormalRecords],
  );

  // 跨境异常数（供顶部红点角标用）
  const crossBorderAbnormalCount = crossBorderAbnormalRecords.length;

   // 统计数据
   const stats = useMemo(() => computeStats(orders), [orders]);
   const monthlyAmount = useMemo(() => computeMonthlyAmount(orders), [orders]);

   // 筛选结果 useMemo 缓存，避免父级无关状态变化时重算
   const filteredOrders = useMemo(() => {
     return orders.filter((o) => {
       if (searchKeyword) {
         const kw = searchKeyword.toLowerCase();
         if (
           !o.productName.toLowerCase().includes(kw) &&
           !o.trackingNumber?.toLowerCase().includes(kw) &&
           !o.shop.toLowerCase().includes(kw)
         ) {
           return false;
         }
       }
       if (filterPlatform !== 'all' && o.platform !== filterPlatform) return false;
       if (filterStatus !== 'all' && o.status !== filterStatus) return false;
       if (filterShop !== 'all' && o.shop !== filterShop) return false;
       return true;
     });
   }, [orders, searchKeyword, filterPlatform, filterStatus, filterShop]);

   // 自动保存提示（右上角小字 2 秒）
   const [showSaved, setShowSaved] = useState(false);
   const savedTimerRef = useRef<number | null>(null);
   function flashSaved() {
     setShowSaved(true);
     if (savedTimerRef.current) clearTimeout(savedTimerRef.current);
     savedTimerRef.current = window.setTimeout(() => setShowSaved(false), 2000);
   }
  // 清理提示定时器
  useEffect(() => {
    return () => {
      if (savedTimerRef.current) {
        clearTimeout(savedTimerRef.current);
        savedTimerRef.current = null;
      }
      if (pushTimerRef.current) {
        window.clearTimeout(pushTimerRef.current);
        pushTimerRef.current = null;
      }
    };
  }, []);

   // 操作：新增订单
   function handleAddOrder() {
    setEditingOrder(null);
    setFormOpen(true);
  }

  // 操作：编辑订单
  function handleEditOrder(order: PurchaseOrder) {
    setEditingOrder(order);
    setFormOpen(true);
  }

  // 操作：保存订单
  function handleSaveOrder(order: PurchaseOrder) {
    if (editingOrder) {
      setOrders((prev) => prev.map((o) => (o.id === order.id ? order : o)));
      toast.success('采购单已更新');
    } else {
      setOrders((prev) => [order, ...prev]);
      toast.success('采购单已添加');
    }
    setFormOpen(false);
    // 保存常用店铺
    if (order.shop) {
      setCommonShops((prev) => {
        if (prev.includes(order.shop)) return prev;
        const next = [order.shop, ...prev].slice(0, 20);
        saveCommonShops(next);
        return next;
      });
    }
  }

  // 操作：删除订单
  function handleDeleteOrder(id: string) {
    setOrders((prev) => prev.filter((o) => o.id !== id));
    toast.success('已删除');
  }

  // 操作：推进状态
  function handleAdvanceStatus(order: PurchaseOrder) {
    const next = nextStatus(order.status);
    if (!next) {
      toast.info('已是最终状态');
      return;
    }
    const now = new Date().toISOString();
    setOrders((prev) =>
      prev.map((o) =>
        o.id === order.id
          ? {
              ...o,
              status: next,
              updatedAt: now,
              shippedAt: next === 'shipped' ? now : o.shippedAt,
              arrivedAt: next === 'arrived' ? now : o.arrivedAt,
              warehousedAt: next === 'warehoused' ? now : o.warehousedAt,
            }
          : o,
      ),
    );
    toast.success(`状态已更新`);
  }

  // 操作：订单状态直接改
  function handleStatusChange(id: string, status: OrderStatus) {
    const now = new Date().toISOString();
    setOrders((prev) =>
      prev.map((o) =>
        o.id === id
          ? {
              ...o,
              status,
              updatedAt: now,
              shippedAt: status === 'shipped' ? now : o.shippedAt,
              arrivedAt: status === 'arrived' ? now : o.arrivedAt,
              warehousedAt: status === 'warehoused' ? now : o.warehousedAt,
            }
          : o,
      ),
    );
    toast.success('状态已更新');
  }

  // 操作：质检保存
  function handleQualityChange(id: string, quality: OrderStatus) {
    // 这里是质检保存的入口，详情抽屉里直接调用
  }

  // 操作：查物流
  function handleQueryLogistics(order: PurchaseOrder | LeadTimeRecord) {
    if (!order.trackingNumber) {
      toast.info('暂无运单号');
      return;
    }
    setLogisticsTrackingNumber(order.trackingNumber);
    setLogisticsCarrier(order.carrier || '');
    setLogisticsOpen(true);
  }

  // 操作：查看订单详情
  function handleViewOrderDetail(order: PurchaseOrder) {
    setDetailOrder(order);
    setDetailOpen(true);
  }

  // 操作：从异常记录跳转
  function handleAbnormalViewOrder(record: AbnormalRecord) {
    if (record.source === 'domestic' && record.order) {
      handleViewOrderDetail(record.order);
    } else if (record.source === 'cross_border') {
      // 切换到跨境时效 tab
      setActiveTab('leadtime');
      toast.info('已切换到跨境时效 tab');
    }
  }

  // 操作：保存质检（从详情抽屉）
  function handleSaveQualityFromDrawer(order: PurchaseOrder) {
    setOrders((prev) => prev.map((o) => (o.id === order.id ? order : o)));
    toast.success('质检结果已保存');
    setDetailOpen(false);
  }

  // 操作：导出运单号
  function handleExportTrackingNumbers() {
    const nums = orders
      .filter((o) => o.trackingNumber)
      .map((o) => o.trackingNumber) as string[];
    if (nums.length === 0) {
      toast.info('暂无运单号可导出');
      return;
    }
    navigator.clipboard
      ?.writeText(nums.join('\n'))
      .then(() => toast.success(`已复制 ${nums.length} 条运单号`))
      .catch(() => toast.error('复制失败，请手动复制'));
  }

  // 操作：设置 key
  function handleKuaidi100KeyChange(key: string) {
    setKuaidi100Key(key);
  }

  // 新增店铺
  function handleAddShop(shop: string) {
    if (!shop.trim()) return;
    setCommonShops((prev) => {
      if (prev.includes(shop)) return prev;
      const next = [shop, ...prev].slice(0, 20);
      saveCommonShops(next);
      return next;
    });
  }

  function handleDeleteShop(shop: string) {
    setCommonShops((prev) => {
      const next = prev.filter((s) => s !== shop);
      saveCommonShops(next);
      return next;
    });
  }

  if (!loaded) {
    return (
      <div className="flex items-center justify-center min-h-[60vh]">
        <div className="text-center text-muted-foreground">
          <div className="animate-spin size-8 border-2 border-primary border-t-transparent rounded-full mx-auto mb-3" />
          <p className="text-sm">正在加载采购数据...</p>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4 relative">
      <Tabs
        value={activeTab}
        onValueChange={(v) => setActiveTab(v as 'orders' | 'leadtime')}
      >
        <div className="flex items-center justify-between">
          <TabsList className="mb-2">
            <TabsTrigger value="orders">采购记录</TabsTrigger>
            <TabsTrigger value="leadtime">
              跨境订单时效
              {crossBorderAbnormalCount > 0 && (
                <span className="ml-1.5 inline-flex items-center justify-center min-w-5 h-5 px-1.5 text-[10px] font-medium text-destructive-foreground bg-destructive rounded-full">
                  {crossBorderAbnormalCount}
                </span>
              )}
            </TabsTrigger>
          </TabsList>

          <div className="h-5 flex items-center">
            <span
              className={
                'text-xs text-muted-foreground transition-opacity duration-300 ' +
                (showSaved ? 'opacity-100' : 'opacity-0 pointer-events-none')
              }
            >
              已自动保存
            </span>
          </div>
        </div>

         <TabsContent value="orders" className="space-y-4 mt-2">
           {/* 统计卡片 */}
            <StatsCards
              total={stats.total}
              inTransit={stats.inTransit}
              arrived={stats.arrived}
              warehoused={stats.warehoused}
              abnormal={abnormalRecords.length}
              monthlyAmount={monthlyAmount}
            />

           {/* 工具栏 */}
           <OrderToolbar
             searchKeyword={searchKeyword}
             onSearchChange={setSearchKeyword}
             filterPlatform={filterPlatform}
             onPlatformChange={setFilterPlatform}
             filterStatus={filterStatus}
             onStatusChange={setFilterStatus}
             filterShop={filterShop}
             onShopChange={setFilterShop}
             shops={commonShops}
             orders={orders}
             onAdd={handleAddOrder}
             kuaidi100Key={kuaidi100Key}
             onKuaidi100KeyChange={handleKuaidi100KeyChange}
           />

           {/* 采购列表 */}
           <OrderList
             orders={filteredOrders}
             onEdit={handleEditOrder}
             onDelete={handleDeleteOrder}
             onStatusChange={handleStatusChange}
             onViewDetail={handleViewOrderDetail}
             onQueryLogistics={handleQueryLogistics}
           />

           {/* 采购时效趋势 + 建议（仅国内采购已到货） */}
           <DomesticLeadTimeSection orders={orders} />

            {/* 异常记录 — 只显示国内采购的异常 */}
            <AbnormalSection
              records={domesticAbnormalRecords}
              onViewOrder={handleAbnormalViewOrder}
              sectionRef={abnormalSectionRef}
              scope="domestic"
            />
         </TabsContent>

         <TabsContent value="leadtime" className="space-y-4 mt-2">
           <LeadTimeSection
             records={leadtimeRecords}
             onChange={setLeadtimeRecords}
             onQueryLogistics={handleQueryLogistics}
             kuaidi100Key={kuaidi100Key}
           />
         </TabsContent>
      </Tabs>

      {/* 新增/编辑订单弹窗 */}
      <OrderFormDialog
        open={formOpen}
        onOpenChange={setFormOpen}
        editingOrder={editingOrder}
        commonShops={commonShops}
        onSave={handleSaveOrder}
        onAddShop={handleAddShop}
        onDeleteShop={handleDeleteShop}
      />

      {/* 订单详情抽屉 */}
      <OrderDetailDrawer
        open={detailOpen}
        onOpenChange={setDetailOpen}
        order={detailOrder}
        onEdit={handleEditOrder}
        onStatusChange={handleStatusChange}
        onQualityChange={(id, quality, replacementTrackingNumber) => {
          setOrders((prev) => {
            const next = prev.map((o) =>
              o.id === id
                ? {
                    ...o,
                    arrivalQuality: quality,
                    replacementTrackingNumber,
                    updatedAt: new Date().toISOString(),
                  }
                : o,
            );
            saveOrders(next);
            return next;
          });
        }}
      />

      {/* 物流查询对话框 */}
      <LogisticsDialog
        open={logisticsOpen}
        onOpenChange={setLogisticsOpen}
        trackingNumber={logisticsTrackingNumber}
        carrierName={logisticsCarrier}
        apiKey={kuaidi100Key}
      />
    </div>
  );
}
