import { useState, useMemo, useEffect, useRef } from 'react';
import { Search, Plus, Settings, Copy, Filter, Download } from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogTrigger,
  DialogClose,
} from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { toast } from 'sonner';
import { PURCHASE_PLATFORMS, ORDER_STATUS, KUAIDI100_API_KEY, KUAIDI100_KEY_STORAGE } from './types';
import type { PurchaseOrder } from './types';
import { scopedStorage } from '@lark-apaas/client-toolkit-lite';
import { exportOrdersToCSV } from '@/lib/exportCsv';

interface OrderToolbarProps {
  searchKeyword: string;
  onSearchChange: (v: string) => void;
  filterPlatform: string;
  onPlatformChange: (v: string) => void;
  filterStatus: string;
  onStatusChange: (v: string) => void;
  filterShop: string;
  onShopChange: (v: string) => void;
  shops: string[];
  orders: PurchaseOrder[];
  onAdd: () => void;
  kuaidi100Key: string;
  onKuaidi100KeyChange: (key: string) => void;
}

export default function OrderToolbar({
  searchKeyword,
  onSearchChange,
  filterPlatform,
  onPlatformChange,
  filterStatus,
  onStatusChange,
  filterShop,
  onShopChange,
  shops,
  orders,
  onAdd,
  kuaidi100Key,
  onKuaidi100KeyChange,
}: OrderToolbarProps) {
  const [settingsOpen, setSettingsOpen] = useState(false);
  const [exportOpen, setExportOpen] = useState(false);
  const [settingsKey, setSettingsKey] = useState(kuaidi100Key);
  const [showFilters, setShowFilters] = useState(false);

  // 搜索输入本地状态 + 300ms 防抖，避免每字触发父级重渲染
  const [localSearch, setLocalSearch] = useState(searchKeyword);
  const debounceRef = useRef<number | null>(null);

  useEffect(() => {
    // 外部值变化时同步本地（如 reset / 清空筛选）
    setLocalSearch(searchKeyword);
  }, [searchKeyword]);

  function handleLocalSearchChange(v: string) {
    setLocalSearch(v);
    if (debounceRef.current) clearTimeout(debounceRef.current);
    debounceRef.current = window.setTimeout(() => {
      onSearchChange(v);
    }, 300);
  }

  // 卸载时清理防抖定时器
  useEffect(() => {
    return () => {
      if (debounceRef.current) {
        clearTimeout(debounceRef.current);
        debounceRef.current = null;
      }
    };
  }, []);

  const allTrackingNumbers = useMemo(
    () => orders.map((o) => o.trackingNumber).filter(Boolean) as string[],
    [orders],
  );

  const exportText = allTrackingNumbers.join('\n');

  function handleCopyTrackingNumbers() {
    if (allTrackingNumbers.length === 0) {
      toast.info('暂无运单号可导出');
      return;
    }
    navigator.clipboard
      ?.writeText(exportText)
      .then(() => toast.success(`已复制 ${allTrackingNumbers.length} 条运单号`))
      .catch(() => toast.error('复制失败'));
  }

  function handleSaveSettings() {
    const key = settingsKey.trim();
    if (!key) {
      toast.error('API Key 不能为空');
      return;
    }
    onKuaidi100KeyChange(key);
    try {
      scopedStorage.setItem(KUAIDI100_KEY_STORAGE, key);
    } catch {
      /* ignore */
    }
    setSettingsOpen(false);
    toast.success('物流设置已保存');
  }

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-wrap items-center gap-2">
        <div className="relative flex-1 min-w-[200px] max-w-md">
          <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
          <Input
            type="search"
            value={localSearch}
            onChange={(e) => handleLocalSearchChange(e.target.value)}
            placeholder="搜索物品名 / 运单号 / 店铺"
            className="bg-background pl-9"
          />
        </div>

        <Button variant="ghost" size="sm" onClick={() => setShowFilters((s) => !s)}>
          <Filter className="size-4 mr-1" />
          筛选
        </Button>

        <div className="flex-1" />

        <Button variant="outline" size="sm" onClick={handleCopyTrackingNumbers}>
          <Copy className="size-4 mr-1" />
          导出运单号
        </Button>

        <Button
          variant="outline"
          size="sm"
          onClick={() => exportOrdersToCSV(orders, `采购记录-${new Date().toISOString().slice(0, 10)}.csv`)}
          title="导出当前筛选结果为CSV"
        >
          <Download className="size-4 mr-1" />
          导出CSV
        </Button>

        <Dialog open={settingsOpen} onOpenChange={setSettingsOpen}>
          <DialogTrigger asChild>
            <Button variant="outline" size="sm">
              <Settings className="size-4 mr-1" />
              物流设置
            </Button>
          </DialogTrigger>
          <DialogContent className="sm:max-w-md">
            <DialogHeader>
              <DialogTitle>物流查询设置</DialogTitle>
            </DialogHeader>
            <div className="space-y-4 py-2">
              <div className="space-y-2">
                <Label htmlFor="kuaidi100-key">快递100 API Key</Label>
                <Input
                  id="kuaidi100-key"
                  value={settingsKey}
                  onChange={(e) => setSettingsKey(e.target.value)}
                  placeholder="输入快递100授权key"
                />
                <p className="text-xs text-muted-foreground">
                  默认已配置企业版 Key（{KUAIDI100_API_KEY.slice(0, 6)}***），可替换为自有 Key。
                </p>
              </div>
            </div>
            <DialogFooter>
              <DialogClose asChild>
                <Button variant="outline">取消</Button>
              </DialogClose>
              <Button onClick={handleSaveSettings}>保存</Button>
            </DialogFooter>
          </DialogContent>
        </Dialog>

        <Button size="sm" onClick={onAdd}>
          <Plus className="size-4 mr-1" />
          新增采购
        </Button>
      </div>

      {showFilters && (
        <div className="flex flex-wrap items-center gap-2 p-3 bg-muted/30 rounded-lg border border-border/40">
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground shrink-0">平台</span>
            <Select value={filterPlatform} onValueChange={onPlatformChange}>
              <SelectTrigger className="h-8 w-[160px] text-xs">
                <SelectValue placeholder="全部平台" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">全部平台</SelectItem>
                {PURCHASE_PLATFORMS.map((p) => (
                  <SelectItem key={p} value={p}>{p}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground shrink-0">状态</span>
            <Select value={filterStatus} onValueChange={onStatusChange}>
              <SelectTrigger className="h-8 w-[140px] text-xs">
                <SelectValue placeholder="全部状态" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">全部状态</SelectItem>
                {ORDER_STATUS.map((s) => (
                  <SelectItem key={s.key} value={s.key}>{s.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground shrink-0">店铺</span>
            <Select value={filterShop} onValueChange={onShopChange}>
              <SelectTrigger className="h-8 w-[180px] text-xs">
                <SelectValue placeholder="全部店铺" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">全部店铺</SelectItem>
                {shops.map((s) => (
                  <SelectItem key={s} value={s} className="text-xs truncate">{s}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>
        </div>
      )}
    </div>
  );
}
