import { Package, Truck, PackageCheck, Archive, AlertTriangle, ShoppingCart, DollarSign } from 'lucide-react';
import { Card, CardContent } from '@/components/ui/card';
import { cn } from '@/lib/utils';

interface StatsCardsProps {
  total: number;
  inTransit: number;
  arrived: number;
  warehoused: number;
  abnormal: number;
  monthlyAmount: number;
}

const items = [
  { key: 'total', label: '采购单总数', icon: ShoppingCart, color: 'text-slate-600', bg: 'bg-slate-100', isAmount: false },
  { key: 'monthlyAmount', label: '本月采购金额', icon: DollarSign, color: 'text-primary', bg: 'bg-primary/10', isAmount: true },
  { key: 'inTransit', label: '运输中', icon: Truck, color: 'text-indigo-600', bg: 'bg-indigo-50', isAmount: false },
  { key: 'arrived', label: '已到货', icon: PackageCheck, color: 'text-emerald-600', bg: 'bg-emerald-50', isAmount: false },
  { key: 'warehoused', label: '已入仓', icon: Archive, color: 'text-teal-600', bg: 'bg-teal-50', isAmount: false },
  { key: 'abnormal', label: '异常单', icon: AlertTriangle, color: 'text-red-600', bg: 'bg-red-50', isAmount: false },
] as const;

export default function StatsCards({ total, inTransit, arrived, warehoused, abnormal, monthlyAmount }: StatsCardsProps) {
  const values: Record<string, number> = { total, inTransit, arrived, warehoused, abnormal, monthlyAmount };

  return (
    <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-6 gap-3">
      {items.map((item) => {
        const Icon = item.icon;
        return (
          <Card key={item.key} className="border border-border/40">
            <CardContent className="p-4">
              <div className="flex items-center gap-3">
                <div className={cn('size-10 rounded-lg flex items-center justify-center shrink-0', item.bg)}>
                  <Icon className={cn('size-5', item.color)} />
                </div>
                <div className="min-w-0 flex-1">
                  <div className="text-xs text-muted-foreground">{item.label}</div>
                  <div className="text-2xl font-bold tabular-nums text-foreground">
                    {item.isAmount
                      ? `¥${values[item.key].toLocaleString()}`
                      : values[item.key]}
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>
        );
      })}
    </div>
  );
}
