import { useState, useEffect } from 'react';
import {
  Drawer,
  DrawerContent,
  DrawerHeader,
  DrawerTitle,
  DrawerFooter,
  DrawerClose,
} from '@/components/ui/drawer';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import { Separator } from '@/components/ui/separator';
import { Label } from '@/components/ui/label';
import {
  Edit2,
  Copy,
  ExternalLink,
  Truck,
  Package,
  Check,
  AlertCircle,
  PackageOpen,
  PackageMinus,
  Palette,
  Puzzle,
  Tag,
  RefreshCw,
} from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import {
  type PurchaseOrder,
  type ArrivalQuality,
  ORDER_STATUS,
} from './types';
import { formatDate, getStatusMeta } from './utils';
import { UniversalLink } from '@lark-apaas/client-toolkit-lite';

interface OrderDetailDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  order: PurchaseOrder | null;
  onEdit: (order: PurchaseOrder) => void;
  onStatusChange: (id: string, status: PurchaseOrder['status']) => void;
  onQualityChange: (id: string, quality: ArrivalQuality, replacementTrackingNumber?: string) => void;
}

const QUALITY_OPTIONS: { key: ArrivalQuality; label: string; icon: typeof Check; color: string }[] = [
  { key: 'normal', label: '正常', icon: Check, color: 'text-emerald-600' },
  { key: 'damaged', label: '破损', icon: PackageOpen, color: 'text-red-600' },
  { key: 'defective', label: '瑕疵', icon: AlertCircle, color: 'text-orange-600' },
  { key: 'missing', label: '漏件', icon: PackageMinus, color: 'text-purple-600' },
  { key: 'color_diff', label: '到件色差', icon: Palette, color: 'text-pink-600' },
  { key: 'accessory_missing', label: '配件缺少', icon: Puzzle, color: 'text-violet-600' },
  { key: 'wrong_item', label: '货不对版', icon: Tag, color: 'text-rose-600' },
  { key: 'replacement', label: '补寄换货', icon: RefreshCw, color: 'text-indigo-600' },
];

function qualityLabel(q?: ArrivalQuality): string {
  if (!q) return '未质检';
  const map: Record<ArrivalQuality, string> = {
    normal: '正常',
    damaged: '破损',
    defective: '瑕疵',
    missing: '漏件',
    color_diff: '到件色差',
    accessory_missing: '配件缺少',
    wrong_item: '货不对版',
    replacement: '补寄换货',
  };
  return map[q];
}

function qualityColor(q?: ArrivalQuality): string {
  if (!q) return 'text-muted-foreground';
  const map: Record<ArrivalQuality, string> = {
    normal: 'text-emerald-600',
    damaged: 'text-red-600',
    defective: 'text-orange-600',
    missing: 'text-purple-600',
    color_diff: 'text-pink-600',
    accessory_missing: 'text-violet-600',
    wrong_item: 'text-rose-600',
    replacement: 'text-indigo-600',
  };
  return map[q];
}

export default function OrderDetailDrawer({
  open,
  onOpenChange,
  order,
  onEdit,
  onStatusChange,
  onQualityChange,
}: OrderDetailDrawerProps) {
  const [quality, setQuality] = useState<ArrivalQuality>('normal');
  const [replacementTrackingNumber, setReplacementTrackingNumber] = useState('');

  useEffect(() => {
    if (order) {
      setQuality(order.arrivalQuality || 'normal');
      setReplacementTrackingNumber(order.replacementTrackingNumber || '');
    }
  }, [order?.id, order?.arrivalQuality, order?.replacementTrackingNumber]);

  if (!order) return null;

  const meta = getStatusMeta(order.status);
  const StatusIcon = meta.icon;
  const isArrived = order.status === 'arrived' || order.status === 'warehoused';

  function handleConfirmQuality() {
    onQualityChange(
      order.id,
      quality,
      quality === 'replacement' ? replacementTrackingNumber.trim() || undefined : undefined,
    );
    toast.success('质检结果已保存');
    onOpenChange(false);
  }

  return (
    <Drawer open={open} onOpenChange={onOpenChange}>
      <DrawerContent className="h-[85vh] sm:max-w-lg sm:h-full sm:ml-auto flex flex-col">
        <DrawerHeader className="shrink-0">
          <DrawerTitle className="flex items-center gap-2">
            <div
              className={cn(
                'size-8 rounded-lg flex items-center justify-center text-white',
                meta.color,
              )}
            >
              <StatusIcon className="size-4" />
            </div>
            采购单详情
          </DrawerTitle>
        </DrawerHeader>

        <div className="flex-1 min-h-0 overflow-y-auto px-4 space-y-4 pb-4">
          {/* 基础信息 */}
          <div className="flex items-start gap-3">
            <div className="flex-1 min-w-0">
              <h3 className="font-semibold text-base">{order.productName}</h3>
              <div className="flex items-center gap-2 mt-1 flex-wrap">
                <Badge variant="outline">{order.platform}</Badge>
                <span className="text-sm text-muted-foreground">{order.shop}</span>
              </div>
            </div>
            <Badge className={cn('text-white border-0', meta.color)}>{meta.label}</Badge>
          </div>

          <Card>
            <CardContent className="p-4 space-y-3 text-sm">
              <div className="flex justify-between gap-4">
                <span className="text-muted-foreground shrink-0">采购平台</span>
                <span className="text-right">{order.platform}</span>
              </div>
              <div className="flex justify-between gap-4">
                <span className="text-muted-foreground shrink-0">对应店铺</span>
                <span className="text-right">{order.shop}</span>
              </div>
              {order.quantity !== undefined && (
                <div className="flex justify-between gap-4">
                  <span className="text-muted-foreground shrink-0">采购数量</span>
                  <span className="text-right tabular-nums">{order.quantity} 件</span>
                </div>
              )}
              {order.amount !== undefined && (
                <div className="flex justify-between gap-4">
                  <span className="text-muted-foreground shrink-0">采购金额</span>
                  <span className="text-right tabular-nums">¥{order.amount.toLocaleString()}</span>
                </div>
              )}
              {order.productUrl && (
                <div className="flex justify-between gap-4 items-start">
                  <span className="text-muted-foreground shrink-0">采购链接</span>
                  <UniversalLink
                    to={order.productUrl}
                    target="_blank"
                    rel="noreferrer"
                    className="text-primary hover:underline text-right truncate max-w-[60%] flex items-center gap-1"
                  >
                    查看链接
                    <ExternalLink className="size-3.5" />
                  </UniversalLink>
                </div>
              )}
              <div className="flex justify-between gap-4">
                <span className="text-muted-foreground shrink-0">创建时间</span>
                <span className="text-right text-xs">{formatDate(order.createdAt)}</span>
              </div>
              {order.remark && (
                <>
                  <Separator />
                  <div>
                    <div className="text-muted-foreground text-xs mb-1">备注</div>
                    <div className="text-sm whitespace-pre-wrap">{order.remark}</div>
                  </div>
                </>
              )}
              {isArrived && (
                <>
                  <Separator />
                  <div className="flex justify-between gap-4 items-center">
                    <span className="text-muted-foreground shrink-0 text-xs">到货质检</span>
                    <span className={cn('text-right font-medium', qualityColor(order.arrivalQuality))}>
                      {qualityLabel(order.arrivalQuality)}
                    </span>
                  </div>
                </>
              )}
            </CardContent>
          </Card>

          {/* 物流信息 */}
          <Card>
            <CardContent className="p-4 space-y-3">
              <div className="text-sm font-semibold flex items-center gap-2">
                <Truck className="size-4" />
                物流信息
              </div>
              {order.trackingNumber ? (
                <>
                  <div className="flex items-center gap-2">
                    <span className="text-xs text-muted-foreground shrink-0">运单号：</span>
                    <code className="flex-1 truncate font-mono text-sm">{order.trackingNumber}</code>
                    <Button
                      size="icon"
                      variant="ghost"
                      className="size-7"
                      onClick={() => {
                        navigator.clipboard?.writeText(order.trackingNumber || '');
                        toast.success('运单号已复制');
                      }}
                      aria-label="复制运单号"
                    >
                      <Copy className="size-3.5" />
                    </Button>
                  </div>
                  {order.expressTimeline && (
                    <div className="text-xs text-muted-foreground">
                      渠道：{order.expressTimeline}
                    </div>
                  )}
                </>
              ) : (
                <div className="text-center py-6 text-muted-foreground text-sm">
                  暂无运输单号，请先编辑并填写运单号
                </div>
              )}
            </CardContent>
          </Card>

          {/* 状态管理 */}
          <Card>
            <CardContent className="p-4 space-y-3">
              <div className="text-sm font-semibold">状态管理</div>
              <div className="flex flex-wrap gap-1.5">
                {ORDER_STATUS.map((s) => {
                  const Icon = s.icon;
                  const active = order.status === s.key;
                  return (
                    <Button
                      key={s.key}
                      size="sm"
                      variant={active ? 'default' : 'outline'}
                      className="h-7 text-xs"
                      onClick={() => onStatusChange(order.id, s.key)}
                    >
                      <Icon className="size-3.5 mr-1" />
                      {s.label}
                    </Button>
                  );
                })}
              </div>

              {isArrived && (
                <>
                  <Separator className="my-3" />
                  <div className="text-xs text-muted-foreground mb-2">到货质检</div>
                  <div className="grid grid-cols-4 gap-2">
                    {QUALITY_OPTIONS.map((opt) => {
                      const Icon = opt.icon;
                      const active = quality === opt.key;
                      return (
                        <Button
                          key={opt.key}
                          type="button"
                          size="sm"
                          variant={active ? 'default' : 'outline'}
                          className="h-10 flex-col gap-0.5"
                          onClick={() => setQuality(opt.key)}
                        >
                          <Icon className={cn('size-4', active ? '' : opt.color)} />
                          <span className="text-xs">{opt.label}</span>
                        </Button>
                      );
                    })}
                  </div>
                  <p className="text-xs text-muted-foreground mt-1.5">
                    标记为异常的订单将自动进入「异常记录」板块
                  </p>

                  {quality === 'replacement' && (
                    <div className="mt-3 space-y-1.5">
                      <Label className="text-xs text-muted-foreground">
                        补寄运单号（可选）
                      </Label>
                      <div className="relative">
                        <Truck className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
                        <Input
                          value={replacementTrackingNumber}
                          onChange={(e) => setReplacementTrackingNumber(e.target.value)}
                          placeholder="填写商家补发的快递单号"
                          className="pl-8 text-sm"
                        />
                      </div>
                    </div>
                  )}

                  <p className="text-xs text-amber-600 mt-2 flex items-center gap-1">
                    <AlertCircle className="size-3.5 shrink-0" />
                    选完后请点击底部「确认质检结果」按钮保存
                  </p>
                </>
              )}
            </CardContent>
          </Card>
        </div>

        <DrawerFooter className="shrink-0 pt-3 mt-0 border-t border-border/50">
          <DrawerClose asChild>
            <Button variant="outline">关闭</Button>
          </DrawerClose>
          <Button variant="secondary" onClick={() => onEdit(order)}>
            <Edit2 className="size-4 mr-1" />
            编辑
          </Button>
          {isArrived && (
            <Button onClick={handleConfirmQuality}>
              <Check className="size-4 mr-1" />
              确认质检结果
            </Button>
          )}
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  );
}
