// 跨境4级预警：超20天注意 / 25天警告 / 30天严重 / 35天严重异常
function getCrossBorderAlert(record: LeadTimeRecord): { level: string; label: string; color: string; bgColor: string; message: string; days: number } | null {
  if (record.arrivedAt || record.status === 'arrived' || record.status === 'warehoused') return null;
  const base = record.orderedAt || (record as any).shippedAt || '';
  if (!base) return null;
  const t = new Date(base).getTime();
  if (isNaN(t)) return null;
  const days = Math.floor((Date.now() - t) / (1000 * 60 * 60 * 24));
  if (days >= 35) {
    return { level: 'critical', label: '严重异常', color: 'text-red-700', bgColor: 'bg-red-100', message: `超${days}天，严重运输异常，疑似丢件，请立即处理`, days };
  }
  if (days >= 30) {
    return { level: 'severe', label: '严重', color: 'text-red-600', bgColor: 'bg-red-50', message: `超${days}天，请货代尽快处理，防止丢件`, days };
  }
  if (days >= 25) {
    return { level: 'warning', label: '警告', color: 'text-orange-600', bgColor: 'bg-orange-50', message: `超${days}天，请联系货代并催促尾端派送`, days };
  }
  if (days >= 20) {
    return { level: 'notice', label: '注意', color: 'text-amber-600', bgColor: 'bg-amber-50', message: `运输已${days}天，请关注物流进度`, days };
  }
  return null;
}

function calcLeadDaysGeneric(orderedAt: string, arrivedAt: string): number | null {
  if (!orderedAt || !arrivedAt) return null;
  const start = new Date(orderedAt).getTime();
  const end = new Date(arrivedAt).getTime();
  if (isNaN(start) || isNaN(end) || end <= start) return null;
  return Math.round(((end - start) / (1000 * 60 * 60 * 24)) * 10) / 10;
}

function calcLeadTimeTrendGeneric(
  items: { orderedAt: string; arrivedAt: string }[],
  days: number,
): LeadTimeTrendItem[] {
  const now = new Date();
  const dateList: string[] = [];
  for (let i = days - 1; i >= 0; i--) {
    const d = new Date(now);
    d.setDate(d.getDate() - i);
    const y = d.getFullYear();
    const m = String(d.getMonth() + 1).padStart(2, '0');
    const day = String(d.getDate()).padStart(2, '0');
    dateList.push(`${y}-${m}-${day}`);
  }

  return dateList.map((date) => {
    const dayItems = items.filter((i) => {
      const d = new Date(i.arrivedAt);
      const y = d.getFullYear();
      const m = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      return `${y}-${m}-${day}` === date;
    });
    const count = dayItems.length;
    if (count === 0) return { date, avgDays: null, count: 0 };
    const validItems = dayItems.filter((i) => i.orderedAt && new Date(i.orderedAt).getTime() > 0);
    if (validItems.length === 0) return { date, avgDays: null, count };
    const totalDays = validItems.reduce((sum, item) => {
      const ordered = new Date(item.orderedAt).getTime();
      const arrived = new Date(item.arrivedAt).getTime();
      if (isNaN(ordered) || isNaN(arrived) || arrived <= ordered) return sum + 0;
      return sum + Math.round(((arrived - ordered) / (1000 * 60 * 60 * 24)) * 10) / 10;
    }, 0);
    return {
      date,
      avgDays: Math.round((totalDays / validItems.length) * 10) / 10,
      count,
    };
  });
}

export default memo(function LeadTimeSection({ records, onChange, onQueryLogistics }: LeadTimeSectionProps) {
  const isMobile = useIsMobile();
  const [searchKeyword, setSearchKeyword] = useState('');
  const [localSearch, setLocalSearch] = useState('');
  const searchDebounceRef = useRef<number | null>(null);

  // 搜索输入防抖 300ms
  function handleLocalSearch(v: string) {
    setLocalSearch(v);
    if (searchDebounceRef.current) clearTimeout(searchDebounceRef.current);
    searchDebounceRef.current = window.setTimeout(() => {
      setSearchKeyword(v);
    }, 300);
  }

  // 卸载时清理防抖定时器
  useEffect(() => {
    return () => {
      if (searchDebounceRef.current) {
        clearTimeout(searchDebounceRef.current);
        searchDebounceRef.current = null;
      }
    };
  }, []);
  const [filterPlatform, setFilterPlatform] = useState<string>('all');
  const [filterStatus, setFilterStatus] = useState<string>('all');
  const [filterShop, setFilterShop] = useState<string>('all');
  const [chartView, setChartView] = useState<'7d' | '30d'>('7d');
   const [listExpanded, setListExpanded] = useState(false);
   const [abnormalExpanded, setAbnormalExpanded] = useState(false);
   const [abnormalFilter, setAbnormalFilter] = useState<string>('all');

  const [formOpen, setFormOpen] = useState(false);
  const [editing, setEditing] = useState<LeadTimeRecord | null>(null);
  const [detailOpen, setDetailOpen] = useState(false);
  const [detailRecord, setDetailRecord] = useState<LeadTimeRecord | null>(null);

  const shops = useMemo(() => {
    const set = new Set(records.map((r) => r.shop).filter(Boolean));
    return Array.from(set).sort();
  }, [records]);

  const filteredRecords = useMemo(() => {
    return records.filter((r) => {
      if (searchKeyword) {
        const kw = searchKeyword.toLowerCase();
        if (
          !r.productName.toLowerCase().includes(kw) &&
          !r.trackingNumber?.toLowerCase().includes(kw) &&
          !r.shop.toLowerCase().includes(kw)
        ) {
          return false;
        }
      }
      if (filterPlatform !== 'all' && r.platform !== filterPlatform) return false;
      if (filterShop !== 'all' && r.shop !== filterShop) return false;
      if (filterStatus !== 'all') {
        const status = getLeadtimeStatus(r);
        if (status !== filterStatus) return false;
      }
      return true;
    });
  }, [records, searchKeyword, filterPlatform, filterShop, filterStatus]);

  const sortedRecords = useMemo(
    () => [...filteredRecords].sort((a, b) => new Date(b.orderedAt).getTime() - new Date(a.orderedAt).getTime()),
    [filteredRecords],
  );

  const visibleRecords = listExpanded ? sortedRecords : sortedRecords.slice(0, LIST_COLLAPSE_THRESHOLD);
  const hasMore = sortedRecords.length > LIST_COLLAPSE_THRESHOLD;

  // 趋势数据：仅基于跨境时效记录，有arrivedAt就计入单量
  const trendData = useMemo(() => {
    const days = chartView === '7d' ? 7 : 30;
    const leadtimeArrived = records
      .filter((r) => r.arrivedAt)
      .map((r) => ({ orderedAt: r.orderedAt, arrivedAt: r.arrivedAt! }));
    return calcLeadTimeTrendGeneric(leadtimeArrived, days);
  }, [records, chartView]);

  // 时效建议：仅基于跨境记录，阈值按跨境节奏（20/25/30天）
  const suggestions = useMemo(() => {
    const arrived = records.filter((r) => r.arrivedAt && r.orderedAt);

    if (arrived.length === 0) {
      const orderedCount = records.length;
      if (orderedCount > 0) {
        return [
          {
            type: 'info' as const,
            icon: 'trending-up' as const,
            title: `共 ${orderedCount} 条跨境在途订单`,
            content: '当前有跨境订单正在运输途中，首单到货后将自动生成时效趋势分析与优化建议。建议重点关注运输超20天未到货的订单，及时联系货代跟进。',
          },
        ];
      }
      return [];
    }

    const totalDays = arrived.reduce((sum, r) => {
      const d = calcLeadDaysGeneric(r.orderedAt, r.arrivedAt!);
      return sum + (d ?? 0);
    }, 0);
    const avgDays = Math.round((totalDays / arrived.length) * 10) / 10;

    const result: LeadTimeSuggestion[] = [];

    if (avgDays > 30) {
      result.push({
        type: 'warning',
        icon: 'trending-up',
        title: `平均时效偏长（${avgDays}天）`,
        content: '跨境订单平均时效超过30天，已处于严重偏慢水平，建议立即评估当前物流渠道/货代服务质量，考虑更换更快的专线或海运渠道，同时与上游供应商协商缩短生产发货周期。',
      });
    } else if (avgDays > 20) {
      result.push({
        type: 'info',
        icon: 'lightbulb',
        title: `平均时效 ${avgDays} 天`,
        content: '跨境时效处于正常偏高水平，建议持续监控核心物流渠道表现，旺季前提前备货并与货代锁定舱位，以应对可能的排仓延误。',
      });
    } else {
      result.push({
        type: 'success',
        icon: 'zap',
        title: `时效良好（平均${avgDays}天）`,
        content: '当前跨境订单时效表现优秀，建议保持现有物流渠道和货代合作，并可尝试将优秀渠道的经验复制到其他站点或品类。',
      });
    }

    // 近7天 vs 上周对比
    const now = Date.now();
    const weekAgo = now - 7 * 24 * 3600 * 1000;
    const twoWeeksAgo = now - 14 * 24 * 3600 * 1000;

    const items = arrived.map((r) => ({ orderedAt: r.orderedAt, arrivedAt: r.arrivedAt! }));
    const lastWeekItems = items.filter((i) => new Date(i.arrivedAt).getTime() >= weekAgo);
    const prevWeekItems = items.filter(
      (i) =>
        new Date(i.arrivedAt).getTime() >= twoWeeksAgo &&
        new Date(i.arrivedAt).getTime() < weekAgo,
    );

    if (lastWeekItems.length > 0 && prevWeekItems.length > 0) {
      const lastAvg =
        lastWeekItems.reduce((s, i) => s + (calcLeadDaysGeneric(i.orderedAt, i.arrivedAt) ?? 0), 0) /
        lastWeekItems.length;
      const prevAvg =
        prevWeekItems.reduce((s, i) => s + (calcLeadDaysGeneric(i.orderedAt, i.arrivedAt) ?? 0), 0) /
        prevWeekItems.length;
      const diff = Math.round((lastAvg - prevAvg) * 10) / 10;
      if (diff < -1) {
        result.push({
          type: 'success',
          icon: 'trending-down',
          title: `近7天时效加快 ${Math.abs(diff)} 天`,
          content: `相比上周，近7天平均时效从 ${Math.round(prevAvg * 10) / 10} 天缩短至 ${Math.round(lastAvg * 10) / 10} 天，跨境物流效率有所提升。`,
        });
      } else if (diff > 1) {
        result.push({
          type: 'warning',
          icon: 'trending-up',
          title: `近7天时效变慢 ${diff} 天`,
          content: `相比上周，近7天平均时效从 ${Math.round(prevAvg * 10) / 10} 天增加到 ${Math.round(lastAvg * 10) / 10} 天，建议排查是否有排仓、尾端派送延误或海关查验等因素。`,
        });
      }
    }

    result.push({
      type: 'info',
      icon: 'target',
      title: `累计到货 ${arrived.length} 单`,
      content: `跨境已到货记录共 ${arrived.length} 条，数据持续积累后趋势分析会更准确。`,
    });

    return result;
  }, [records]);
  const alertRecords = useMemo(() => {
    const list: { record: LeadTimeRecord; alert: NonNullable<ReturnType<typeof getCrossBorderAlert>> }[] = [];
    records.forEach((r) => {
      const alert = getCrossBorderAlert(r);
      if (alert) list.push({ record: r, alert });
    });
    return list.sort((a, b) => b.alert.days - a.alert.days);
  }, [records]);

  const ALERT_LEVELS = [
    { key: 'critical', label: '严重异常(35天+)', color: 'text-red-700', bg: 'bg-red-100' },
    { key: 'severe', label: '严重(30天+)', color: 'text-red-600', bg: 'bg-red-50' },
    { key: 'warning', label: '警告(25天+)', color: 'text-orange-600', bg: 'bg-orange-50' },
    { key: 'notice', label: '注意(20天+)', color: 'text-amber-600', bg: 'bg-amber-50' },
  ];

  const filteredAlerts = abnormalFilter === 'all'
    ? alertRecords
    : alertRecords.filter((r) => r.alert.level === abnormalFilter);
  const visibleAlerts = abnormalExpanded ? filteredAlerts : filteredAlerts.slice(0, LIST_COLLAPSE_THRESHOLD);
  const alertHasMore = filteredAlerts.length > LIST_COLLAPSE_THRESHOLD;

  // 图表配置（useMemo 缓存，避免重渲染）
  const chartOption = useMemo<EChartsOption>(
    () => ({
      tooltip: {
        trigger: 'axis',
        axisPointer: { type: 'cross' },
      },
      legend: { bottom: 0, type: 'scroll' },
      grid: { left: '3%', right: '4%', bottom: '18%', containLabel: true },
      xAxis: {
        type: 'category',
        boundaryGap: true,
        data: trendData.map((d) => d.date.slice(5)),
        axisLabel: { fontSize: 10 },
      },
      yAxis: [
        {
          type: 'value',
          name: '时效(天)',
          position: 'left',
          axisLabel: { fontSize: 10 },
          splitLine: { lineStyle: { type: 'dashed', opacity: 0.5 } },
          minInterval: 1,
        },
        {
          type: 'value',
          name: '到货单数',
          position: 'right',
          axisLabel: { fontSize: 10 },
          splitLine: { show: false },
          minInterval: 1,
        },
      ],
      series: [
        {
          name: '平均时效',
          type: 'line',
          yAxisIndex: 0,
          smooth: true,
          data: trendData.map((d) => d.avgDays),
          lineStyle: { color: CHART_COLORS.avg, width: 2 },
          itemStyle: { color: CHART_COLORS.avg },
          connectNulls: true,
        },
        {
          name: '到货单数',
          type: 'bar',
          yAxisIndex: 1,
          data: trendData.map((d) => d.count),
          itemStyle: { color: CHART_COLORS.count, borderRadius: [4, 4, 0, 0] },
          barWidth: 12,
        },
      ],
    }),
    [trendData],
  );

  function handleExportTrackingNumbers() {
    const nums = sortedRecords.map((r) => r.trackingNumber).filter(Boolean) as string[];
    if (nums.length === 0) {
      toast.info('暂无运单号可导出');
      return;
    }
    navigator.clipboard
      ?.writeText(nums.join('\n'))
      .then(() => toast.success(`已复制 ${nums.length} 条运单号`))
      .catch(() => toast.error('复制失败'));
  }

  function handleExportCsv() {
    if (sortedRecords.length === 0) {
      toast.info('暂无订单可导出');
      return;
    }
    try {
      const headers = [
        '订单编号',
        '平台',
        '店铺',
        '商品名称',
        '售价(USD)',
        '数量',
        '运单号',
        '物流渠道',
        '下单时间',
        '到货时间',
        '时效天数',
        '状态',
        '到货质量',
        '补寄运单号',
        '备注',
      ];
      const rows = sortedRecords.map((r) => {
        const leadDays = r.orderedAt && r.arrivedAt
          ? calcLeadDays(r.orderedAt, r.arrivedAt)
          : null;
        return [
          r.id,
          r.platform || '',
          r.shop || '',
          (r.productName || '').replace(/,/g, '，'),
          r.salePrice != null ? String(r.salePrice) : '',
          r.quantity != null ? String(r.quantity) : '',
          r.trackingNumber || '',
          r.carrier || '',
          r.orderedAt ? formatDate(r.orderedAt) : '',
          r.arrivedAt ? formatDate(r.arrivedAt) : '',
          leadDays != null ? String(leadDays) : '',
          getStatusMeta(r.status || 'ordered').label,
          r.arrivalQuality || '',
          r.replacementTrackingNumber || '',
          (r.remark || '').replace(/,/g, '，').replace(/\n/g, ' '),
        ];
      });
      const csvContent =
        '\uFEFF' +
        [headers, ...rows]
          .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(','))
          .join('\n');
      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `跨境订单-${new Date().toISOString().slice(0, 10)}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      toast.success(`已导出 ${sortedRecords.length} 条跨境订单`);
    } catch (e) {
      toast.error('导出失败，请重试');
    }
  }

  function handleAdd() {
    setEditing(null);
    setFormOpen(true);
  }

  function handleEdit(record: LeadTimeRecord) {
    setEditing(record);
    setFormOpen(true);
  }

  function handleViewDetail(record: LeadTimeRecord) {
    setDetailRecord(record);
    setDetailOpen(true);
  }

  function handleSaveRecord(record: LeadTimeRecord) {
    if (editing) {
      onChange(records.map((r) => (r.id === record.id ? record : r)));
      toast.success('时效记录已更新');
    } else {
      onChange([record, ...records]);
      toast.success('时效记录已添加');
    }
    setFormOpen(false);
  }

  function handleDelete(id: string) {
    onChange(records.filter((r) => r.id !== id));
    toast.success('已删除');
  }

  // 推进跨境时效记录状态
  function handleAdvanceStatus(record: LeadTimeRecord) {
    const currentStatus = getLeadtimeStatus(record);
    const statuses: OrderStatus[] = [
      'ordered',
      'pending_ship',
      'shipped',
      'in_transit',
      'arrived',
      'warehoused',
    ];
    const idx = statuses.indexOf(currentStatus);
    if (idx < 0 || idx >= statuses.length - 1) return;
    const next = statuses[idx + 1];
    const now = new Date().toISOString();
    const updated: LeadTimeRecord = {
      ...record,
      status: next,
      updatedAt: now,
    };
    if (next === 'shipped' && !record.trackingNumber) {
      // 推进到已发货但无运单号，不自动设置，保留用户手动填
    }
    if (next === 'arrived') {
      updated.arrivedAt = record.arrivedAt || now;
      if (!updated.arrivalQuality) updated.arrivalQuality = 'normal';
    }
    if (next === 'warehoused') {
      updated.warehousedAt = record.warehousedAt || now;
      if (!updated.arrivalQuality) updated.arrivalQuality = 'normal';
    }
    onChange(records.map((r) => (r.id === record.id ? updated : r)));
    const nextMeta = ORDER_STATUS.find((s) => s.key === next);
    toast.success(`已推进至「${nextMeta?.label || next}」`);
  }

  return (
    <div className="space-y-4">
      {/* 图表 + 建议 */}
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-4">
        <Card className="lg:col-span-2">
          <CardHeader className="pb-2 flex-row items-center justify-between">
            <CardTitle className="text-base flex items-center gap-2">
              <TrendingUp className="size-4 text-primary" />
              跨境订单时效趋势
            </CardTitle>
            <Tabs value={chartView} onValueChange={(v) => setChartView(v as '7d' | '30d')}>
              <TabsList className="h-7">
                <TabsTrigger value="7d" className="text-xs h-6 px-3">近7天</TabsTrigger>
                <TabsTrigger value="30d" className="text-xs h-6 px-3">近30天</TabsTrigger>
              </TabsList>
            </Tabs>
          </CardHeader>
          <CardContent>
            {/* 有记录就显示图表，不设门槛 */}
            <ReactECharts
              option={chartOption}
              theme="ud"
              className="h-[280px] w-full"
              notMerge
              lazyUpdate
            />
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="pb-2">
            <CardTitle className="text-base flex items-center gap-2">
              <Lightbulb className="size-4 text-amber-500" />
              时效建议
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            {suggestions.length === 0 ? (
              <p className="text-sm text-muted-foreground">
                有到货记录后自动生成时效分析建议
              </p>
            ) : (
              suggestions.map((s, i) => {
                const iconMap = {
                  'trending-up': TrendingUp,
                  'trending-down': TrendingUp,
                  zap: Zap,
                  target: Target,
                  lightbulb: Lightbulb,
                };
                const Icon = iconMap[s.icon];
                const colorMap = {
                  warning: 'text-amber-500 bg-amber-50',
                  info: 'text-blue-500 bg-blue-50',
                  success: 'text-emerald-500 bg-emerald-50',
                };
                return (
                  <div key={i} className="p-3 rounded-lg border border-border/40">
                    <div className="flex items-center gap-2 mb-1.5">
                      <div className={cn('size-7 rounded-md flex items-center justify-center', colorMap[s.type])}>
                        <Icon className="size-3.5" />
                      </div>
                      <span className="font-medium text-sm">{s.title}</span>
                    </div>
                    <p className="text-xs text-muted-foreground leading-relaxed">{s.content}</p>
                  </div>
                );
              })
            )}
          </CardContent>
        </Card>
      </div>

      {/* 工具栏 */}
      <Card>
        <CardContent className="p-4 space-y-3">
          <div className="flex flex-wrap items-center gap-2">
            <div className="relative flex-1 min-w-[200px] max-w-md">
              <Search className="pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2 text-muted-foreground" />
              <Input
                type="search"
                value={localSearch}
                onChange={(e) => handleLocalSearch(e.target.value)}
                placeholder="搜索产品/运单号/店铺"
                className="bg-background pl-9"
              />
            </div>

            <Select value={filterPlatform} onValueChange={setFilterPlatform}>
              <SelectTrigger className="h-8 w-[140px] text-xs">
                <SelectValue placeholder="全部平台" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">全部平台</SelectItem>
                 {CROSSBORDER_PLATFORMS.map((p) => (
                   <SelectItem key={p} value={p}>{p}</SelectItem>
                 ))}
              </SelectContent>
            </Select>

            <Select value={filterStatus} onValueChange={setFilterStatus}>
              <SelectTrigger className="h-8 w-[120px] text-xs">
                <SelectValue placeholder="全部状态" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">全部状态</SelectItem>
                {ORDER_STATUS.map((s) => (
                  <SelectItem key={s.key} value={s.key}>{s.label}</SelectItem>
                ))}
              </SelectContent>
            </Select>

            {shops.length > 0 && (
              <Select value={filterShop} onValueChange={setFilterShop}>
                <SelectTrigger className="h-8 w-[160px] text-xs">
                  <SelectValue placeholder="全部店铺" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">全部店铺</SelectItem>
                  {shops.map((s) => (
                    <SelectItem key={s} value={s} className="text-xs truncate">{s}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}

            <div className="flex-1" />

            <Button variant="outline" size="sm" onClick={handleExportTrackingNumbers}>
              <Copy className="size-4 mr-1" />
              导出运单号
            </Button>
            <Button variant="outline" size="sm" onClick={handleExportCsv} title="导出当前筛选结果为CSV">
              <Download className="size-4 mr-1" />
              导出CSV
            </Button>
            <Button size="sm" onClick={handleAdd}>
              <Plus className="size-4 mr-1" />
              新增跨境订单
            </Button>
          </div>
        </CardContent>
      </Card>

      {/* 列表 */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base flex items-center justify-between">
            <span className="flex items-center gap-2">
              <CalendarClock className="size-4 text-primary" />
              跨境订单列表
            </span>
            <Badge variant="secondary">共 {sortedRecords.length} 条</Badge>
          </CardTitle>
        </CardHeader>
        <CardContent className="pt-0">
          {sortedRecords.length === 0 ? (
            <div className="text-center py-12 text-muted-foreground text-sm">
              暂无跨境订单，点击「新增跨境订单」添加
            </div>
          ) : (
            <div className="space-y-2">
              {visibleRecords.map((r) => {
                const status = getLeadtimeStatus(r);
                const statusMeta = ORDER_STATUS.find((s) => s.key === status) || ORDER_STATUS[0];
                const StatusIcon = statusMeta.icon;
                const leadDays = calcLeadDays(r.orderedAt, r.arrivedAt);
                return (
                  <div
                    key={r.id}
                    className="p-3 rounded-lg border border-border/40 hover:border-border/80 transition-colors"
                  >
                    <div className="flex items-start gap-3">
                      <div
                        className={cn(
                          'size-9 rounded-lg flex items-center justify-center shrink-0 text-white',
                          statusMeta.color,
                        )}
                      >
                        <StatusIcon className="size-4" />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-start justify-between gap-2">
                          <div className="min-w-0 flex-1">
                            <div
                              className="font-medium text-sm truncate cursor-pointer hover:text-primary"
                              onClick={() => handleViewDetail(r)}
                            >
                              {r.productName}
                            </div>
                            <div className="flex items-center gap-2 mt-1 flex-wrap">
                              <Badge variant="outline" className="text-xs h-5 px-1.5">
                                {r.platform}
                              </Badge>
                              <span className="text-xs text-muted-foreground truncate max-w-[180px]">
                                {r.shop || '—'}
                              </span>
                            </div>
                          </div>
                          <Badge className={cn('shrink-0 text-white border-0', statusMeta.color)}>
                            {statusMeta.label}
                          </Badge>
                        </div>

                        <div className="flex items-center gap-3 mt-2 text-xs text-muted-foreground flex-wrap">
                          {leadDays !== null && (
                            <span className="font-medium tabular-nums text-foreground">
                              {leadDays} 天
                            </span>
                          )}
                          {r.salePrice !== undefined && (
                            <span>售价：${r.salePrice.toLocaleString()}</span>
                          )}
                          {r.quantity !== undefined && (
                            <span>{r.quantity} 件</span>
                          )}
                          {r.trackingNumber && (
                            <span className="flex items-center gap-1 font-mono">
                              <Truck className="size-3" />
                              {r.trackingNumber}
                            </span>
                          )}
                        </div>

                        <div className="flex items-center gap-1 mt-2 flex-wrap">
                          <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => handleEdit(r)}>
                            <Edit2 className="size-3.5 mr-1" />
                            编辑
                          </Button>
                          <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => handleViewDetail(r)}>
                            详情
                          </Button>
                          {r.trackingNumber && (
                            <Button
                              variant="outline"
                              size="sm"
                              className="h-7 text-xs"
                              onClick={() => onQueryLogistics(r)}
                            >
                              <Truck className="size-3.5 mr-1" />
                              查物流
                            </Button>
                          )}
                          {getStatusIndex(status) < ORDER_STATUS.length - 2 && (
                            <Button
                              variant="outline"
                              size="sm"
                              className="h-7 text-xs"
                              onClick={() => handleAdvanceStatus(r)}
                            >
                              推进到{ORDER_STATUS[getStatusIndex(status) + 1]?.label || ''}
                              <ArrowRight className="size-3.5 ml-1" />
                            </Button>
                          )}
                          <div className="flex-1" />
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 text-xs text-red-500 hover:text-red-600 hover:bg-red-50"
                            onClick={() => handleDelete(r.id)}
                          >
                            <Trash2 className="size-3.5 mr-1" />
                            删除
                          </Button>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })}

              {hasMore && (
                <div className="flex justify-center pt-2">
                  <Button variant="ghost" size="sm" onClick={() => setListExpanded((e) => !e)}>
                    {listExpanded ? (
                      <>收起 <ChevronUp className="size-4 ml-1" /></>
                    ) : (
                      <>展开更多（还有 {sortedRecords.length - LIST_COLLAPSE_THRESHOLD} 条）<ChevronDown className="size-4 ml-1" /></>
                    )}
                  </Button>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* 跨境时效预警（4级） */}
      <Card>
        <CardHeader className="pb-2">
          <CardTitle className="text-base flex items-center gap-2">
            <AlertTriangle className="size-4 text-amber-500" />
            跨境时效预警
            <Badge variant="secondary" className="ml-1">
              共 {alertRecords.length} 条
            </Badge>
          </CardTitle>
        </CardHeader>
        <CardContent className="pt-0 space-y-3">
          <div className="flex flex-wrap gap-2">
            <Button
              size="sm"
              variant={abnormalFilter === 'all' ? 'default' : 'outline'}
              className="h-7 text-xs"
              onClick={() => setAbnormalFilter('all')}
            >
              全部 {alertRecords.length}
            </Button>
            {ALERT_LEVELS.map((lv) => {
              const count = alertRecords.filter((r) => r.alert.level === lv.key).length;
              return (
                <Button
                  key={lv.key}
                  size="sm"
                  variant={abnormalFilter === lv.key ? 'default' : 'outline'}
                  className="h-7 text-xs"
                  onClick={() => setAbnormalFilter(lv.key)}
                >
                  {lv.label} {count}
                </Button>
              );
            })}
          </div>

          {filteredAlerts.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground text-sm">
              暂无超期订单
            </div>
          ) : (
            <div className="space-y-2">
              {visibleAlerts.map((r, i) => {
                const lv = ALERT_LEVELS.find((l) => l.key === r.alert.level) || ALERT_LEVELS[0];
                return (
                  <div
                    key={`${r.record.id}-${i}`}
                    className="p-3 rounded-lg border border-border/40 bg-card hover:border-border/80 transition-colors cursor-pointer"
                    onClick={() => handleViewDetail(r.record)}
                  >
                    <div className="flex items-start gap-2">
                      <div
                        className={cn(
                          'size-7 rounded-md flex items-center justify-center shrink-0 mt-0.5',
                          lv.bg,
                        )}
                      >
                        <AlertTriangle className={cn('size-3.5', lv.color)} />
                      </div>
                      <div className="flex-1 min-w-0">
                        <div className="flex items-center justify-between gap-2">
                          <span className="font-medium text-sm truncate">{r.record.productName}</span>
                          <Badge variant="outline" className={cn('shrink-0 text-xs', lv.color)}>
                            {lv.label}
                          </Badge>
                        </div>
                        <div className="text-xs text-muted-foreground mt-1">{r.alert.message}</div>
                      </div>
                    </div>
                  </div>
                );
              })}

              {alertHasMore && (
                <div className="flex justify-center pt-1">
                  <Button variant="ghost" size="sm" onClick={() => setAbnormalExpanded((e) => !e)}>
                    {abnormalExpanded ? (
                      <>收起 <ChevronUp className="size-4 ml-1" /></>
                    ) : (
                      <>展开更多（还有 {filteredAlerts.length - LIST_COLLAPSE_THRESHOLD} 条）<ChevronDown className="size-4 ml-1" /></>
                    )}
                  </Button>
                </div>
              )}
            </div>
          )}
        </CardContent>
      </Card>

      {/* 新增/编辑 弹窗 */}
      <LeadTimeFormDialog
        open={formOpen}
        onOpenChange={setFormOpen}
        editing={editing}
        onSave={handleSaveRecord}
      />

      {/* 详情抽屉 */}
      <LeadTimeDetailDrawer
        open={detailOpen}
        onOpenChange={setDetailOpen}
        record={detailRecord}
        onEdit={(r) => {
          setDetailOpen(false);
          handleEdit(r);
        }}
        onDelete={(id) => {
          setDetailOpen(false);
          handleDelete(id);
        }}
      />
    </div>
  );
})

// ===== 新增/编辑 弹窗 =====
interface LeadTimeFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editing: LeadTimeRecord | null;
  onSave: (record: LeadTimeRecord) => void;
}

function LeadTimeFormDialog({ open, onOpenChange, editing, onSave }: LeadTimeFormDialogProps) {
  const [platform, setPlatform] = useState<string>(CROSSBORDER_PLATFORMS[0]);
  const [status, setStatus] = useState('ordered');
  const [orderedAt, setOrderedAt] = useState('');
  const [arrivedAt, setArrivedAt] = useState('');
  const [shop, setShop] = useState('');
  const [productName, setProductName] = useState('');
  const [carrier, setCarrier] = useState('');
  const [trackingNumber, setTrackingNumber] = useState('');
  const [salePrice, setSalePrice] = useState('');
  const [quantity, setQuantity] = useState('');
  const [remark, setRemark] = useState('');
  const [arrivalQuality, setArrivalQuality] = useState<ArrivalQuality>('normal');
  const [replacementTrackingNumber, setReplacementTrackingNumber] = useState('');

  const isEdit = !!editing;
  const isArrived = status === 'arrived' || status === 'warehoused';

  const handleInit = useCallback(() => {
    if (editing) {
      setPlatform(editing.platform);
      setStatus(editing.status || 'ordered');
      setOrderedAt(
        editing.orderedAt
          ? new Date(editing.orderedAt).toISOString().slice(0, 16)
          : '',
      );
      setArrivedAt(
        editing.arrivedAt
          ? new Date(editing.arrivedAt).toISOString().slice(0, 16)
          : '',
      );
      setShop(editing.shop);
      setProductName(editing.productName);
      setCarrier(editing.carrier || '');
      setTrackingNumber(editing.trackingNumber || '');
      setSalePrice(editing.salePrice?.toString() || '');
      setQuantity(editing.quantity?.toString() || '');
      setRemark(editing.remark || '');
      setArrivalQuality(editing.arrivalQuality || 'normal');
      setReplacementTrackingNumber(editing.replacementTrackingNumber || '');
    } else {
      const now = new Date();
      setPlatform(CROSSBORDER_PLATFORMS[0]);
      setStatus('ordered');
      setOrderedAt(formatDateTimeLocal(now));
      setArrivedAt('');
      setShop('');
      setProductName('');
      setCarrier('');
      setTrackingNumber('');
      setSalePrice('');
      setQuantity('');
      setRemark('');
      setArrivalQuality('normal');
      setReplacementTrackingNumber('');
    }
  }, [editing]);

  useState(() => {
    if (open) handleInit();
  });

  // 用 useEffect 处理 open 变化时的初始化
  // 弹窗打开时初始化表单数据（新增时清空，编辑时预填）
  useEffect(() => {
    if (open) {
      handleInit();
    }
  }, [open, handleInit]);

  function handleSubmit(e: FormEvent) {
    e.preventDefault();
    if (!productName.trim()) {
      toast.error('请填写产品名称');
      return;
    }

    const now = new Date().toISOString();
    const record: LeadTimeRecord = {
      id: editing?.id || genId(),
      platform,
      shop: shop.trim(),
      productName: productName.trim(),
      salePrice: salePrice ? parseFloat(salePrice) : undefined,
      quantity: quantity ? parseInt(quantity, 10) : undefined,
      carrier: carrier.trim() || undefined,
      trackingNumber: trackingNumber.trim() || undefined,
      orderedAt: orderedAt ? new Date(orderedAt).toISOString() : now,
      arrivedAt: arrivedAt ? new Date(arrivedAt).toISOString() : undefined,
      status: status as LeadTimeRecord['status'],
      arrivalQuality: isArrived ? arrivalQuality : undefined,
      replacementTrackingNumber:
        isArrived && arrivalQuality === 'replacement'
          ? replacementTrackingNumber.trim() || undefined
          : undefined,
      remark: remark.trim() || undefined,
      createdAt: editing?.createdAt || now,
      updatedAt: now,
    };

    onSave(record);
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-3xl max-h-[90vh] flex flex-col p-0 overflow-hidden">
        <DialogHeader className="px-6 pt-6 pb-2 shrink-0">
          <DialogTitle>{isEdit ? '编辑时效记录' : '新增时效记录'}</DialogTitle>
        </DialogHeader>

        <ScrollArea className="flex-1 min-h-0 px-6">
          <form id="leadtime-form" onSubmit={handleSubmit} className="space-y-3 py-2">
            <div className="grid grid-cols-2 gap-x-5 gap-y-3">
              {/* 左列 */}
              <div className="space-y-1.5">
                <Label>销售平台</Label>
                <Select value={platform} onValueChange={setPlatform}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {CROSSBORDER_PLATFORMS.map((p) => (
                      <SelectItem key={p} value={p}>{p}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <div className="space-y-1.5">
                <Label>运输状态</Label>
                <Select value={status} onValueChange={setStatus}>
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {ORDER_STATUS.map((s) => (
                      <SelectItem key={s.key} value={s.key}>{s.label}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>

              <div className="space-y-1.5">
                <Label>下单时间</Label>
                <Input
                  type="datetime-local"
                  value={orderedAt}
                  onChange={(e) => setOrderedAt(e.target.value)}
                />
              </div>
              <div className="space-y-1.5">
                <Label>到货时间</Label>
                <Input
                  type="datetime-local"
                  value={arrivedAt}
                  onChange={(e) => setArrivedAt(e.target.value)}
                />
              </div>

              <div className="space-y-1.5">
                <Label>店铺名称</Label>
                <Input
                  value={shop}
                  onChange={(e) => setShop(e.target.value)}
                  placeholder="如：AMZ 美国店"
                />
              </div>
              <div className="space-y-1.5">
                <Label>产品名称</Label>
                <Input
                  value={productName}
                  onChange={(e) => setProductName(e.target.value)}
                  placeholder="如：无线蓝牙耳机"
                />
              </div>

              <div className="space-y-1.5">
                <Label>快递渠道</Label>
                <Input
                  value={carrier}
                  onChange={(e) => setCarrier(e.target.value)}
                  placeholder="如：云途物流"
                />
              </div>
              <div className="space-y-1.5">
                <Label>运单号</Label>
                <Input
                  value={trackingNumber}
                  onChange={(e) => setTrackingNumber(e.target.value)}
                  placeholder="运输单号"
                />
              </div>

              <div className="space-y-1.5">
                <Label>当地售价（$）</Label>
                <Input
                  type="number"
                  value={salePrice}
                  onChange={(e) => setSalePrice(e.target.value)}
                  placeholder="美元"
                />
              </div>
              <div className="space-y-1.5">
                <Label>件数</Label>
                <Input
                  type="number"
                  value={quantity}
                  onChange={(e) => setQuantity(e.target.value)}
                  placeholder="件数"
                />
              </div>

              <div className="col-span-2 space-y-1.5">
                <Label>备注</Label>
                <Textarea
                  value={remark}
                  onChange={(e) => setRemark(e.target.value)}
                  rows={2}
                  placeholder="其他备注信息..."
                />
              </div>
            </div>

            {isArrived && (
              <>
                <Separator />
                <div className="space-y-1.5">
                  <Label className="text-xs text-muted-foreground">到货质检</Label>
                  <div className="grid grid-cols-4 gap-1.5">
                    {QUALITY_OPTIONS.map((opt) => {
                      const Icon = opt.icon;
                      const active = arrivalQuality === opt.key;
                      return (
                        <Button
                          key={opt.key}
                          type="button"
                          size="sm"
                          variant={active ? 'default' : 'outline'}
                          className="h-9 flex-col gap-0.5 py-1"
                          onClick={() => setArrivalQuality(opt.key)}
                        >
                          <Icon className={cn('size-3.5', active ? '' : opt.color)} />
                          <span className="text-[11px] leading-tight">{opt.label}</span>
                        </Button>
                      );
                    })}
                  </div>

                  {arrivalQuality === 'replacement' && (
                    <div className="space-y-1">
                      <Label className="text-xs text-muted-foreground">
                        补寄运单号（可选）
                      </Label>
                      <div className="relative">
                        <Truck className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
                        <Input
                          value={replacementTrackingNumber}
                          onChange={(e) => setReplacementTrackingNumber(e.target.value)}
                          placeholder="填写商家补发的快递单号"
                          className="pl-8 text-sm h-9"
                        />
                      </div>
                    </div>
                  )}
                </div>
              </>
            )}

            <div className="h-2" />
          </form>
        </ScrollArea>

        <DialogFooter className="px-6 py-4 border-t border-border/50 shrink-0">
          <Button variant="outline" onClick={() => onOpenChange(false)}>取消</Button>
          <Button type="submit" form="leadtime-form">
            {isEdit ? '保存修改' : '确认添加'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

// ===== 详情抽屉 =====
interface LeadTimeDetailDrawerProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  record: LeadTimeRecord | null;
  onEdit: (record: LeadTimeRecord) => void;
  onDelete: (id: string) => void;
}

function LeadTimeDetailDrawer({
  open,
  onOpenChange,
  record,
  onEdit,
  onDelete,
}: LeadTimeDetailDrawerProps) {
  if (!record) return null;

  const status = getLeadtimeStatus(record);
  const statusMeta = ORDER_STATUS.find((s) => s.key === status) || ORDER_STATUS[0];
  const StatusIcon = statusMeta.icon;
  const leadDays = calcLeadDays(record.orderedAt, record.arrivedAt);

  function qualityLabel(q?: ArrivalQuality): string {
    if (!q) return '未质检';
    const map: Record<ArrivalQuality, string> = {
      normal: '正常',
      damaged: '破损',
      defective: '瑕疵',
      missing: '漏件',
      color_diff: '到件色差',
      accessory_missing: '配件缺少',
      wrong_item: '货不对版',
      replacement: '补寄换货',
    };
    return map[q];
  }

  return (
    <Drawer open={open} onOpenChange={onOpenChange}>
      <DrawerContent className="h-[85vh] sm:max-w-md sm:h-full sm:ml-auto flex flex-col">
        <DrawerHeader className="shrink-0">
          <DrawerTitle className="flex items-center gap-2">
            <div
              className={cn(
                'size-8 rounded-lg flex items-center justify-center text-white',
                statusMeta.color,
              )}
            >
              <StatusIcon className="size-4" />
            </div>
            时效记录详情
          </DrawerTitle>
        </DrawerHeader>

        <div className="flex-1 min-h-0 overflow-y-auto px-4 space-y-4 pb-4">
          <div>
            <h3 className="font-semibold text-base">{record.productName}</h3>
            <div className="flex items-center gap-2 mt-1">
              <Badge variant="outline">{record.platform}</Badge>
              <span className="text-sm text-muted-foreground">{record.shop || '—'}</span>
            </div>
          </div>

          <Card>
            <CardContent className="p-4 space-y-2 text-sm">
              <div className="flex justify-between">
                <span className="text-muted-foreground">时效</span>
                <span className="font-medium">
                  {leadDays !== null ? `${leadDays} 天` : '未到货'}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">下单时间</span>
                <span className="text-xs">{formatDate(record.orderedAt)}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">到货时间</span>
                <span className="text-xs">{record.arrivedAt ? formatDate(record.arrivedAt) : '—'}</span>
              </div>
              {record.salePrice !== undefined && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">当地售价</span>
                  <span className="tabular-nums">${record.salePrice.toLocaleString()}</span>
                </div>
              )}
              {record.quantity !== undefined && (
                <div className="flex justify-between">
                  <span className="text-muted-foreground">件数</span>
                  <span>{record.quantity} 件</span>
                </div>
              )}
              <div className="flex justify-between">
                <span className="text-muted-foreground">快递渠道</span>
                <span>{record.carrier || '—'}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-muted-foreground">运单号</span>
                <code className="font-mono text-xs">{record.trackingNumber || '—'}</code>
              </div>
              <Separator />
              <div className="flex justify-between">
                <span className="text-muted-foreground text-xs">到货质检</span>
                <span className="font-medium text-xs">{qualityLabel(record.arrivalQuality)}</span>
              </div>
              {record.remark && (
                <>
                  <Separator />
                  <div>
                    <div className="text-muted-foreground text-xs mb-1">备注</div>
                    <div className="text-sm whitespace-pre-wrap">{record.remark}</div>
                  </div>
                </>
              )}
            </CardContent>
          </Card>
        </div>

        <DrawerFooter className="shrink-0 pt-3 mt-0 border-t border-border/50">
          <DrawerClose asChild>
            <Button variant="outline">关闭</Button>
          </DrawerClose>
          <Button variant="secondary" onClick={() => onEdit(record)}>
            <Edit2 className="size-4 mr-1" />
            编辑
          </Button>
          <Button variant="destructive" onClick={() => onDelete(record.id)}>
            <Trash2 className="size-4 mr-1" />
            删除
          </Button>
        </DrawerFooter>
      </DrawerContent>
    </Drawer>
  );
}
