import { useState, memo, useRef, useEffect, type FormEvent } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  Edit2,
  Trash2,
  ArrowRight,
  Truck,
  Copy,
  X,
  ChevronDown,
  ChevronUp,
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Card, CardContent } from '@/components/ui/card';
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '@/components/ui/alert-dialog';
import { cn } from '@/lib/utils';
import { toast } from 'sonner';
import { Check } from 'lucide-react';
import {
  type PurchaseOrder,
  type OrderStatus,
  ORDER_STATUS,
  LIST_COLLAPSE_THRESHOLD,
} from './types';
import { formatDate, getStatusMeta, nextStatus } from './utils';

interface OrderListProps {
  orders: PurchaseOrder[];
  onEdit: (order: PurchaseOrder) => void;
  onDelete: (id: string) => void;
  onStatusChange: (id: string, status: OrderStatus) => void;
  onViewDetail: (order: PurchaseOrder) => void;
  onQueryLogistics: (order: PurchaseOrder) => void;
}

export default memo(function OrderList({
  orders,
  onEdit,
  onDelete,
  onStatusChange,
  onViewDetail,
  onQueryLogistics,
}: OrderListProps) {
  const navigate = useNavigate();
  const [expanded, setExpanded] = useState(false);
  const [copiedTrackingId, setCopiedTrackingId] = useState<string | null>(null);
  const copyTimerRef = useRef<number | null>(null);
  const visibleOrders = expanded ? orders : orders.slice(0, LIST_COLLAPSE_THRESHOLD);
  const hasMore = orders.length > LIST_COLLAPSE_THRESHOLD;

  // 清理复制反馈定时器
  useEffect(() => {
    return () => {
      if (copyTimerRef.current) {
        clearTimeout(copyTimerRef.current);
        copyTimerRef.current = null;
      }
    };
  }, []);

  function handleCopyTracking(trackingNumber: string, orderId: string) {
    navigator.clipboard?.writeText(trackingNumber || '');
    setCopiedTrackingId(orderId);
    if (copyTimerRef.current) clearTimeout(copyTimerRef.current);
    copyTimerRef.current = window.setTimeout(() => setCopiedTrackingId(null), 1500);
  }

  if (orders.length === 0) {
    return (
      <Card className="border-dashed">
        <CardContent className="py-12 flex flex-col items-center justify-center text-center">
          <Truck className="size-12 text-muted-foreground/30 mb-3" />
          <p className="text-muted-foreground text-sm">暂无采购单，点击「新增采购」添加第一条</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <div className="space-y-3">
      <div className="space-y-2">
        {visibleOrders.map((order) => {
          const meta = getStatusMeta(order.status);
          const StatusIcon = meta.icon;
          const next = nextStatus(order.status);

          return (
            <Card key={order.id} className="border border-border/40 hover:border-border/80 transition-colors">
              <CardContent className="p-4">
                <div className="flex items-start gap-3">
                  <div
                    className={cn(
                      'size-10 rounded-lg flex items-center justify-center shrink-0 text-white',
                      meta.color,
                    )}
                  >
                    <StatusIcon className="size-5" />
                  </div>

                  <div className="flex-1 min-w-0">
                    <div className="flex items-start justify-between gap-2">
                      <div className="min-w-0 flex-1">
                        <h3
                          className="font-medium text-sm truncate cursor-pointer hover:text-primary transition-colors"
                          onClick={() => onViewDetail(order)}
                        >
                          {order.productName}
                        </h3>
                        <div className="flex items-center gap-2 mt-1 flex-wrap">
                          <Badge variant="outline" className="text-xs h-5 px-1.5">
                            {order.platform}
                          </Badge>
                          <span className="text-xs text-muted-foreground truncate max-w-[200px]">
                            {order.shop || '未设置店铺'}
                          </span>
                        </div>
                      </div>
                      <Badge
                        className={cn('shrink-0 text-white border-0', meta.color)}
                      >
                        {meta.label}
                      </Badge>
                    </div>

                    <div className="flex items-center gap-4 mt-2 text-xs text-muted-foreground flex-wrap">
                      {order.quantity !== undefined && (
                        <span>数量：{order.quantity} 件</span>
                      )}
                      {order.amount !== undefined && (
                        <span className="tabular-nums">¥{order.amount.toLocaleString()}</span>
                      )}
                      {order.trackingNumber && (
                        <span className="inline-flex items-center gap-1.5 text-xs text-muted-foreground">
                          <Truck className="size-3.5 shrink-0 text-muted-foreground/60" />
                          <span className="shrink-0">运单</span>
                          <span className="font-mono text-foreground/70 truncate max-w-[160px]">{order.trackingNumber}</span>
                          <Button
                            variant="ghost"
                            size="icon"
                            className="!h-5 !w-5 shrink-0"
                            onClick={() => handleCopyTracking(order.trackingNumber!, order.id)}
                            onKeyDown={(e) => {
                              if (e.key === 'Enter' || e.key === ' ') {
                                e.preventDefault();
                                handleCopyTracking(order.trackingNumber!, order.id);
                              }
                            }}
                            aria-label={copiedTrackingId === order.id ? '已复制' : '复制运单号'}
                            title={copiedTrackingId === order.id ? '已复制' : '复制运单号'}
                          >
                            {copiedTrackingId === order.id ? (
                              <Check className="size-3.5 text-emerald-500" />
                            ) : (
                              <Copy className="size-3.5" />
                            )}
                          </Button>
                        </span>
                      )}
                      <span>{formatDate(order.createdAt)}</span>
                    </div>

                    <div className="flex items-center gap-1 mt-3 flex-wrap">
                      <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => onEdit(order)}>
                        <Edit2 className="size-3.5 mr-1" />
                        编辑
                      </Button>
                      <Button variant="ghost" size="sm" className="h-7 text-xs" onClick={() => onViewDetail(order)}>
                        详情
                      </Button>
                      {next && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-7 text-xs"
                          onClick={() => onStatusChange(order.id, next)}
                        >
                          推进到{getStatusMeta(next).label}
                          <ArrowRight className="size-3.5 ml-1" />
                        </Button>
                      )}
                      {order.trackingNumber && (
                        <Button
                          variant="outline"
                          size="sm"
                          className="h-7 text-xs"
                          onClick={() => onQueryLogistics(order)}
                        >
                          <Truck className="size-3.5 mr-1" />
                          查物流
                        </Button>
                      )}
                      <div className="flex-1" />
                      <AlertDialog>
                        <AlertDialogTrigger asChild>
                          <Button variant="ghost" size="sm" className="h-7 text-xs text-red-500 hover:text-red-600 hover:bg-red-50">
                            <Trash2 className="size-3.5 mr-1" />
                            删除
                          </Button>
                        </AlertDialogTrigger>
                        <AlertDialogContent>
                          <AlertDialogHeader>
                            <AlertDialogTitle>确认删除</AlertDialogTitle>
                            <AlertDialogDescription>
                              删除后无法恢复，确定要删除这条采购单吗？
                            </AlertDialogDescription>
                          </AlertDialogHeader>
                          <AlertDialogFooter>
                            <AlertDialogCancel>取消</AlertDialogCancel>
                            <AlertDialogAction
                              className="bg-red-500 hover:bg-red-600"
                              onClick={() => onDelete(order.id)}
                            >
                              删除
                            </AlertDialogAction>
                          </AlertDialogFooter>
                        </AlertDialogContent>
                      </AlertDialog>
                    </div>
                  </div>
                </div>
              </CardContent>
            </Card>
          );
        })}
      </div>

      {hasMore && (
        <div className="flex justify-center pt-2">
          <Button variant="ghost" size="sm" onClick={() => setExpanded((e) => !e)}>
            {expanded ? (
              <>
                收起
                <ChevronUp className="size-4 ml-1" />
              </>
            ) : (
              <>
                展开更多（还有 {orders.length - LIST_COLLAPSE_THRESHOLD} 条）
                <ChevronDown className="size-4 ml-1" />
              </>
            )}
          </Button>
        </div>
      )}
    </div>
  );
});
