import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit-lite';
import type { PurchaseOrder } from '@/pages/PurchaseOrderPage/types';
import { normalizePlatformForDisplay, formatDate, getStatusMeta } from '@/pages/PurchaseOrderPage/utils';

/**
 * 将采购订单导出为 CSV
 */
export function exportOrdersToCSV(orders: PurchaseOrder[], filename?: string) {
  if (orders.length === 0) {
    toast.info('暂无订单可导出');
    return;
  }

  try {
    // 表头
    const headers = [
      '订单编号',
      '采购平台',
      '店铺',
      '商品名称',
      '商品链接',
      '数量',
      '金额(元)',
      '运单号',
      '物流公司',
      '物流链接',
      '状态',
       '到货质量',
       '补寄运单号',
       '下单时间',
      '发货时间',
      '到货时间',
      '备注',
      '质量备注',
    ];

    // 行数据
    const rows = orders.map((o) => [
      o.id,
      normalizePlatformForDisplay(o.platform),
      o.shop || '',
      (o.productName || '').replace(/,/g, '，'),
      o.productUrl || '',
      o.quantity != null ? String(o.quantity) : '',
      o.amount != null ? String(o.amount) : '',
      o.trackingNumber || '',
      o.carrier || '',
      o.trackingUrl || '',
      getStatusMeta(o.status).label,
       o.arrivalQuality || '',
       o.replacementTrackingNumber || '',
       formatDate(o.purchaseTime || o.purchaseDate || o.createdAt),
      o.shippedAt ? formatDate(o.shippedAt) : '',
      o.arrivedAt ? formatDate(o.arrivedAt) : '',
      (o.remark || '').replace(/,/g, '，').replace(/\n/g, ' '),
      (o.qualityNote || '').replace(/,/g, '，').replace(/\n/g, ' '),
    ]);

    // BOM 头 + CSV 内容（Excel 打开不乱码）
    const csvContent =
      '\uFEFF' +
      [headers, ...rows]
        .map((row) => row.map((cell) => `"${String(cell).replace(/"/g, '""')}"`).join(','))
        .join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    const dateStr = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = filename || `采购记录-${dateStr}.csv`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);

    toast.success(`已导出 ${orders.length} 条采购记录`);
  } catch (e) {
    logger.error('导出CSV失败:', String(e));
    toast.error('导出失败，请重试');
  }
}
