// ========== 质检状态 ==========
export type ArrivalQuality = 'normal' | 'damaged' | 'defective' | 'missing' | 'color_diff' | 'accessory_missing' | 'wrong_item' | 'replacement';

// ========== 采购单 ==========
export interface PurchaseOrder {
  id: string;
  platform: PurchasePlatform;
  shop: string;
  productName: string;
  productUrl?: string;
  quantity?: number;
  amount?: number;
  trackingNumber?: string;
  carrier?: string;
  trackingUrl?: string;
  expressTimeline?: string;
  status: OrderStatus;
  remark?: string;
  qualityNote?: string;
  createdAt: string;
  updatedAt: string;
  shippedAt?: string;
  arrivedAt?: string;
  warehousedAt?: string;
  purchaseTime?: string;
  purchaseDate?: string;
  arrivalQuality?: ArrivalQuality;
  replacementTrackingNumber?: string;
}

// ========== 时效记录 ==========
export interface LeadTimeRecord {
  id: string;
  platform: string;
  shop: string;
  productName: string;
  salePrice?: number;
  quantity?: number;
  carrier?: string;
  trackingNumber?: string;
  orderedAt: string;
  arrivedAt?: string;
  warehousedAt?: string;
  status?: OrderStatus;
  arrivalQuality?: ArrivalQuality;
  replacementTrackingNumber?: string;
  remark?: string;
  createdAt: string;
  updatedAt: string;
}

export interface LeadTimeTrendItem {
  date: string;
  avgDays: number | null;
  count: number;
}

export interface LeadTimeSuggestion {
  type: 'warning' | 'info' | 'success';
  icon: 'trending-up' | 'trending-down' | 'zap' | 'target' | 'lightbulb';
  title: string;
  content: string;
}

// ========== 异常记录 ==========
export type AbnormalType =
  | 'shipping_delay'
  | 'arrival_damaged'
  | 'arrival_defective'
  | 'quantity_missing'
  | 'arrival_color_diff'
  | 'arrival_accessory_missing'
  | 'arrival_wrong_item'
  | 'arrival_replacement'
  | 'cross_border_20d'
  | 'cross_border_25d'
  | 'cross_border_30d'
  | 'cross_border_35d';

export type AbnormalSource = 'domestic' | 'cross_border';

export interface AbnormalRecord {
  type: AbnormalType;
  source: AbnormalSource;
  order?: PurchaseOrder;
  leadTimeRecord?: LeadTimeRecord;
  productName: string;
  shop: string;
  days?: number;
  triggerInfo: string;
  suggestion: string;
}

export interface LeadTimeAbnormalRecord {
  type: AbnormalType;
  record: LeadTimeRecord;
  triggerInfo: string;
  suggestion: string;
}

