import { useState, useEffect, type FormEvent } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { Textarea } from '@/components/ui/textarea';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { X, Check, AlertCircle, PackageOpen, PackageMinus, Palette, Puzzle, Tag, RefreshCw, Truck } from 'lucide-react';
import { ScrollArea } from '@/components/ui/scroll-area';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import {
  type PurchaseOrder,
  type ArrivalQuality,
  PURCHASE_PLATFORMS,
  ORDER_STATUS,
} from './types';
import { genId, formatDate } from './utils';

interface OrderFormDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  editingOrder: PurchaseOrder | null;
  commonShops: string[];
  onSave: (order: PurchaseOrder) => void;
  onAddShop: (shop: string) => void;
  onDeleteShop: (shop: string) => void;
}

const QUALITY_OPTIONS: { key: ArrivalQuality; label: string; icon: typeof Check; color: string }[] = [
  { key: 'normal', label: '正常', icon: Check, color: 'text-emerald-600' },
  { key: 'damaged', label: '破损', icon: PackageOpen, color: 'text-red-600' },
  { key: 'defective', label: '瑕疵', icon: AlertCircle, color: 'text-orange-600' },
  { key: 'missing', label: '漏件', icon: PackageMinus, color: 'text-purple-600' },
  { key: 'color_diff', label: '到件色差', icon: Palette, color: 'text-pink-600' },
  { key: 'accessory_missing', label: '配件缺少', icon: Puzzle, color: 'text-violet-600' },
  { key: 'wrong_item', label: '货不对版', icon: Tag, color: 'text-rose-600' },
  { key: 'replacement', label: '补寄换货', icon: RefreshCw, color: 'text-indigo-600' },
];

function pad(n: number) {
  return String(n).padStart(2, '0');
}

function formatDateTimeLocal(d: Date): string {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

function normalizeShopName(name: string, shops: string[]): string {
  const trimmed = name.trim();
  if (!trimmed) return '';
  // 如果输入的是已有店铺的模糊匹配，直接用全名
  const match = shops.find((s) => s.toLowerCase().includes(trimmed.toLowerCase()));
  if (match) return match;
  return trimmed;
}

export default function OrderFormDialog({
  open,
  onOpenChange,
  editingOrder,
  commonShops,
  onSave,
  onAddShop,
  onDeleteShop,
}: OrderFormDialogProps) {
  const [platform, setPlatform] = useState<string>(PURCHASE_PLATFORMS[2]);
  const [status, setStatus] = useState<string>('ordered');
  const [purchaseTime, setPurchaseTime] = useState('');
  const [arrivedAt, setArrivedAt] = useState('');
  const [shop, setShop] = useState('');
  const [productName, setProductName] = useState('');
  const [quantity, setQuantity] = useState('');
  const [amount, setAmount] = useState('');
  const [carrier, setCarrier] = useState('');
  const [trackingNumber, setTrackingNumber] = useState('');
  const [remark, setRemark] = useState('');
  const [arrivalQuality, setArrivalQuality] = useState<ArrivalQuality>('normal');
  const [replacementTrackingNumber, setReplacementTrackingNumber] = useState('');

  const isEdit = !!editingOrder;
  const isArrived = status === 'arrived' || status === 'warehoused';

  useEffect(() => {
    if (open) {
      if (editingOrder) {
        setPlatform(editingOrder.platform);
        setStatus(editingOrder.status);
        setPurchaseTime(
          editingOrder.purchaseTime
            ? formatDateTimeLocal(new Date(editingOrder.purchaseTime))
            : '',
        );
        setArrivedAt(
          editingOrder.arrivedAt
            ? formatDateTimeLocal(new Date(editingOrder.arrivedAt))
            : '',
        );
        setShop(editingOrder.shop);
        setProductName(editingOrder.productName);
        setQuantity(editingOrder.quantity?.toString() || '');
        setAmount(editingOrder.amount?.toString() || '');
        setCarrier(editingOrder.expressTimeline || '');
        setTrackingNumber(editingOrder.trackingNumber || '');
        setRemark(editingOrder.remark || '');
        setArrivalQuality(editingOrder.arrivalQuality || 'normal');
        setReplacementTrackingNumber(editingOrder.replacementTrackingNumber || '');
      } else {
        const now = new Date();
        setPlatform(PURCHASE_PLATFORMS[2]);
        setStatus('ordered');
        setPurchaseTime(formatDateTimeLocal(now));
        setArrivedAt('');
        setShop('');
        setProductName('');
        setQuantity('');
        setAmount('');
        setCarrier('');
        setTrackingNumber('');
        setRemark('');
        setArrivalQuality('normal');
        setReplacementTrackingNumber('');
      }
    }
  }, [open, editingOrder]);

  function handleSubmit(e: FormEvent) {
    e.preventDefault();

    if (!productName.trim()) {
      toast.error('请填写采购物品名称');
      return;
    }
    if (!shop.trim()) {
      toast.error('请填写对应店铺');
      return;
    }
    if (!trackingNumber.trim()) {
      toast.error('请填写运输单号');
      return;
    }

    const normalizedShop = normalizeShopName(shop, commonShops);
    if (normalizedShop && !commonShops.includes(normalizedShop)) {
      onAddShop(normalizedShop);
    }

    const now = new Date().toISOString();
    const order: PurchaseOrder = {
      id: editingOrder?.id || genId(),
      platform: platform as PurchaseOrder['platform'],
      shop: normalizedShop,
      productName: productName.trim(),
      quantity: quantity ? parseInt(quantity, 10) : undefined,
      amount: amount ? parseFloat(amount) : undefined,
      trackingNumber: trackingNumber.trim() || undefined,
      expressTimeline: carrier.trim() || undefined,
      status: status as PurchaseOrder['status'],
      remark: remark.trim() || undefined,
      createdAt: editingOrder?.createdAt || now,
      updatedAt: now,
      purchaseTime: purchaseTime ? new Date(purchaseTime).toISOString() : undefined,
      shippedAt: status === 'shipped' || status === 'in_transit' ? now : undefined,
       arrivalQuality: isArrived ? arrivalQuality : undefined,
       replacementTrackingNumber:
         isArrived && arrivalQuality === 'replacement'
           ? replacementTrackingNumber.trim() || undefined
           : undefined,
       arrivedAt: isArrived && arrivedAt ? new Date(arrivedAt).toISOString() : undefined,
     };

    onSave(order);
    onOpenChange(false);
    toast.success(isEdit ? '采购单已更新' : '采购单已添加');
  }

  function handleQuickShop(s: string) {
    setShop(s);
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
       <DialogContent className="sm:max-w-3xl max-h-[90vh] !flex !flex-col p-0 !gap-0 overflow-hidden">
         <DialogHeader className="px-6 pt-6 pb-4 shrink-0">
           <DialogTitle>{isEdit ? '编辑采购单' : '新增采购单'}</DialogTitle>
         </DialogHeader>

         <ScrollArea className="flex-1 px-6 min-h-0">
           <form id="purchase-order-form" onSubmit={handleSubmit} className="py-2">
             <div className="grid grid-cols-2 gap-4">
               {/* 左栏 */}
               <div className="space-y-4">
                 <div className="grid grid-cols-2 gap-3">
                   <div className="space-y-1.5">
                     <Label>采购平台</Label>
                     <Select value={platform} onValueChange={setPlatform}>
                       <SelectTrigger>
                         <SelectValue />
                       </SelectTrigger>
                       <SelectContent>
                         {PURCHASE_PLATFORMS.map((p) => (
                           <SelectItem key={p} value={p}>{p}</SelectItem>
                         ))}
                       </SelectContent>
                     </Select>
                   </div>
                   <div className="space-y-1.5">
                     <Label>到货状态</Label>
                     <Select value={status} onValueChange={setStatus}>
                       <SelectTrigger>
                         <SelectValue />
                       </SelectTrigger>
                       <SelectContent>
                         {ORDER_STATUS.map((s) => (
                           <SelectItem key={s.key} value={s.key}>{s.label}</SelectItem>
                         ))}
                       </SelectContent>
                     </Select>
                   </div>
                 </div>

                 <div className="grid grid-cols-2 gap-3">
                   <div className="space-y-1.5">
                     <Label>采购时间</Label>
                     <Input
                       type="datetime-local"
                       value={purchaseTime}
                       onChange={(e) => setPurchaseTime(e.target.value)}
                     />
                   </div>
                   {isArrived && (
                     <div className="space-y-1.5">
                       <Label>到货时间</Label>
                       <Input
                         type="datetime-local"
                         value={arrivedAt}
                         onChange={(e) => setArrivedAt(e.target.value)}
                       />
                     </div>
                   )}
                 </div>

                 <div className="space-y-1.5">
                   <Label>对应店铺</Label>
                   <div className="relative">
                     <Input
                       value={shop}
                       onChange={(e) => setShop(e.target.value)}
                       placeholder="输入店铺名，如：AMZ 主店 · 张三"
                       list="shop-options"
                       autoComplete="off"
                     />
                     <datalist id="shop-options">
                       {commonShops.map((s) => (
                         <option key={s} value={s}>{s}</option>
                       ))}
                     </datalist>
                   </div>
                   {commonShops.length > 0 && (
                     <div className="flex flex-wrap gap-1.5 pt-1">
                       {commonShops.slice(0, 6).map((s) => (
                         <div
                           key={s}
                           className={cn(
                             'group inline-flex items-center gap-1 text-xs pl-2.5 pr-1 py-0.5 rounded-full border transition-colors',
                             shop === s
                               ? 'bg-primary text-primary-foreground border-primary'
                               : 'bg-muted/50 text-muted-foreground border-border/60 hover:bg-muted hover:text-foreground',
                           )}
                         >
                           <button
                             type="button"
                             onClick={() => handleQuickShop(s)}
                             className="leading-tight"
                           >
                             {s}
                           </button>
                           <button
                             type="button"
                             onClick={(e) => {
                               e.stopPropagation();
                               onDeleteShop(s);
                             }}
                             className="h-4 w-4 inline-flex items-center justify-center rounded-full opacity-50 hover:opacity-100 hover:bg-foreground/10 transition-opacity shrink-0"
                             aria-label={`删除 ${s}`}
                             title="删除该常用店铺"
                           >
                             <X className="size-3" />
                           </button>
                         </div>
                       ))}
                       {shop.trim() && !commonShops.includes(shop.trim()) && (
                         <button
                           type="button"
                           onClick={() => onAddShop(shop.trim())}
                           className="text-xs px-2 py-0.5 rounded-full border border-dashed border-primary/50 text-primary hover:bg-primary/10 transition-colors"
                         >
                           + 保存「{shop.trim()}」
                         </button>
                       )}
                     </div>
                   )}
                   <p className="text-xs text-muted-foreground">
                     输入后自动补全常用店铺，新店铺可点击保存
                   </p>
                 </div>

                 <div className="space-y-1.5">
                   <Label>
                     采购物品名称 <span className="text-red-500">*</span>
                   </Label>
                   <Input
                     value={productName}
                     onChange={(e) => setProductName(e.target.value)}
                     placeholder="如：无线蓝牙耳机（白色款）"
                   />
                 </div>
               </div>

               {/* 右栏 */}
               <div className="space-y-4">
                 <div className="grid grid-cols-2 gap-3">
                   <div className="space-y-1.5">
                     <Label>采购数量（可选）</Label>
                     <Input
                       type="number"
                       value={quantity}
                       onChange={(e) => setQuantity(e.target.value)}
                       placeholder="件数"
                     />
                   </div>
                   <div className="space-y-1.5">
                     <Label>采购金额（可选）</Label>
                     <Input
                       type="number"
                       value={amount}
                       onChange={(e) => setAmount(e.target.value)}
                       placeholder="元"
                     />
                   </div>
                 </div>

                 <div className="space-y-1.5">
                   <Label>
                     运输信息 <span className="text-red-500">*</span>
                   </Label>
                   <div className="grid grid-cols-5 gap-2">
                     <div className="col-span-2">
                       <Input
                         value={carrier}
                         onChange={(e) => setCarrier(e.target.value)}
                         placeholder="快递渠道，如：顺丰"
                         list="carrier-options"
                       />
                       <datalist id="carrier-options">
                         {['顺丰速运', '中通快递', '圆通速递', '韵达快递', '极兔速递', '云途物流', '燕文物流', '递四方', '中国邮政'].map((c) => (
                           <option key={c} value={c}>{c}</option>
                         ))}
                       </datalist>
                     </div>
                     <div className="col-span-3">
                       <Input
                         value={trackingNumber}
                         onChange={(e) => setTrackingNumber(e.target.value)}
                         placeholder="运输单号"
                       />
                     </div>
                   </div>
                 </div>

                 <div className="space-y-1.5">
                   <Label>备注（可选）</Label>
                   <Textarea
                     value={remark}
                     onChange={(e) => setRemark(e.target.value)}
                     placeholder="其他注意事项..."
                     rows={3}
                   />
                 </div>

                 {isArrived && (
                   <div className="space-y-2 pt-2 border-t border-border/50">
                     <Label>到货质检</Label>
                     <div className="grid grid-cols-4 gap-2">
                       {QUALITY_OPTIONS.map((opt) => {
                         const Icon = opt.icon;
                         const active = arrivalQuality === opt.key;
                         return (
                           <Button
                             key={opt.key}
                             type="button"
                             size="sm"
                             variant={active ? 'default' : 'outline'}
                             className="h-10 flex-col gap-0.5"
                             onClick={() => setArrivalQuality(opt.key)}
                           >
                             <Icon className={cn('size-4', active ? '' : opt.color)} />
                             <span className="text-xs">{opt.label}</span>
                           </Button>
                         );
                       })}
                     </div>
                      <p className="text-xs text-muted-foreground">
                        标记为异常的订单将自动进入「异常记录」板块
                      </p>

                      {arrivalQuality === 'replacement' && (
                        <div className="mt-2 space-y-1.5">
                          <Label className="text-xs text-muted-foreground">
                            补寄运单号（可选）
                          </Label>
                          <div className="relative">
                            <Truck className="pointer-events-none absolute left-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
                            <Input
                              value={replacementTrackingNumber}
                              onChange={(e) => setReplacementTrackingNumber(e.target.value)}
                              placeholder="填写商家补发的快递单号"
                              className="pl-8 text-sm"
                            />
                          </div>
                        </div>
                      )}
                    </div>
                 )}
               </div>
             </div>

             <div className="h-2" />
           </form>
         </ScrollArea>

        <DialogFooter className="px-6 py-4 border-t border-border/50 shrink-0 mt-0">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            取消
          </Button>
          <Button type="submit" form="purchase-order-form">
            {isEdit ? '保存修改' : '确认添加'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
