import { useState, memo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { ChevronDown, ChevronUp, AlertTriangle, Lightbulb, Eye } from 'lucide-react';
import { cn } from '@/lib/utils';
import {
  type AbnormalType,
  type AbnormalRecord,
  ABNORMAL_TYPE_META,
  LIST_COLLAPSE_THRESHOLD,
} from './types';

interface AbnormalSectionProps {
  records: AbnormalRecord[];
  onViewOrder?: (record: AbnormalRecord) => void;
  sectionRef?: React.RefObject<HTMLDivElement>;
  scope?: 'domestic' | 'cross_border' | 'all';
}

const DOMESTIC_TAB_ORDER: Array<{ key: AbnormalType | 'all'; label: string }> = [
  { key: 'all', label: '全部' },
  { key: 'shipping_delay', label: '运输超7天' },
  { key: 'arrival_damaged', label: '到库破损' },
  { key: 'arrival_defective', label: '到库瑕疵' },
  { key: 'quantity_missing', label: '数量漏件' },
  { key: 'arrival_color_diff', label: '到件色差' },
  { key: 'arrival_accessory_missing', label: '配件缺少' },
  { key: 'arrival_wrong_item', label: '货不对版' },
  { key: 'arrival_replacement', label: '补寄换货' },
];

const CROSS_BORDER_TAB_ORDER: Array<{ key: AbnormalType | 'all'; label: string }> = [
  { key: 'all', label: '全部' },
  { key: 'cross_border_20d', label: '跨境超20天' },
  { key: 'cross_border_25d', label: '跨境超25天' },
  { key: 'cross_border_30d', label: '跨境超30天' },
  { key: 'cross_border_35d', label: '跨境超35天' },
  { key: 'arrival_damaged', label: '到库破损' },
  { key: 'arrival_defective', label: '到库瑕疵' },
  { key: 'quantity_missing', label: '数量漏件' },
  { key: 'arrival_color_diff', label: '到件色差' },
  { key: 'arrival_accessory_missing', label: '配件缺少' },
  { key: 'arrival_wrong_item', label: '货不对版' },
  { key: 'arrival_replacement', label: '补寄换货' },
];

export default memo(function AbnormalSection({ records, onViewOrder, sectionRef, scope = 'all' }: AbnormalSectionProps) {
  const tabOrder = scope === 'domestic' ? DOMESTIC_TAB_ORDER : scope === 'cross_border' ? CROSS_BORDER_TAB_ORDER : DOMESTIC_TAB_ORDER;
  const [activeType, setActiveType] = useState<AbnormalType | 'all'>('all');
  const [expanded, setExpanded] = useState(false);

  const filteredRecords = activeType === 'all'
    ? records
    : records.filter((r) => r.type === activeType);

  const visibleRecords = expanded ? filteredRecords : filteredRecords.slice(0, LIST_COLLAPSE_THRESHOLD);
  const hasMore = filteredRecords.length > LIST_COLLAPSE_THRESHOLD;

  const total = records.length;

  function getCount(type: AbnormalType | 'all') {
    if (type === 'all') return total;
    return records.filter((r) => r.type === type).length;
  }

  return (
    <Card ref={sectionRef} id="abnormal-section">
      <CardHeader className="pb-3">
        <CardTitle className="text-base flex items-center gap-2">
           <AlertTriangle className="size-4 text-amber-500" />
           {scope === 'cross_border' ? '跨境异常记录' : '异常记录'}
          <Badge variant="secondary" className="ml-1">
            共 {total} 条
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="pt-0">
        {/* 分类标签 */}
        <div className="flex flex-wrap gap-2 mb-4">
          {tabOrder.map((tab) => {
            const count = getCount(tab.key);
            const active = activeType === tab.key;
            const meta = tab.key !== 'all' ? ABNORMAL_TYPE_META[tab.key] : null;
            return (
              <Button
                key={tab.key}
                size="sm"
                variant={active ? 'default' : 'outline'}
                className="h-7 text-xs"
                onClick={() => setActiveType(tab.key)}
              >
                {meta && <meta.icon className={cn('size-3.5 mr-1', active ? '' : meta.color)} />}
                {tab.label}
                <Badge variant="secondary" className="ml-1 h-5 px-1 text-[10px]">
                  {count}
                </Badge>
              </Button>
            );
          })}
        </div>

        {/* 异常列表 */}
        {filteredRecords.length === 0 ? (
          <div className="text-center py-8 text-muted-foreground text-sm">
             暂无异常记录，继续保持！
           </div>
         ) : (
           <div className="space-y-2">
             {visibleRecords.map((record, i) => {
               const meta = ABNORMAL_TYPE_META[record.type];
               const Icon = meta.icon;
               const isCrossBorder = record.source === 'cross_border';
               return (
                 <div
                   key={`${record.type}-${record.leadTimeRecord?.id ?? record.order?.id}-${i}`}
                  className="p-3 rounded-lg border border-border/40 hover:border-border/80 transition-colors bg-card"
                >
                  <div className="flex items-start gap-2">
                    <div
                      className={cn(
                        'size-7 rounded-md flex items-center justify-center shrink-0 mt-0.5',
                        record.type === 'shipping_delay' && 'bg-amber-50',
                        record.type === 'arrival_damaged' && 'bg-red-50',
                        record.type === 'arrival_defective' && 'bg-orange-50',
                        record.type === 'quantity_missing' && 'bg-purple-50',
                        record.type === 'cross_border_20d' && 'bg-amber-50',
                        record.type === 'cross_border_25d' && 'bg-orange-50',
                        record.type === 'cross_border_30d' && 'bg-red-50',
                        record.type === 'cross_border_35d' && 'bg-red-100',
                      )}
                    >
                      <Icon className={cn('size-3.5', meta.color)} />
                    </div>
                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between gap-2">
                        <span
                          className="font-medium text-sm truncate cursor-pointer hover:text-primary"
                          onClick={() => onViewOrder?.(record)}
                        >
                          {record.productName}
                        </span>
                        <Badge
                          variant="outline"
                          className={cn('shrink-0 text-xs', meta.color)}
                        >
                          {meta.label}
                        </Badge>
                      </div>
                      <div className="flex items-center gap-2 mt-1 text-xs text-muted-foreground">
                        <Badge variant="secondary" className="text-[10px] h-4 px-1 font-normal">
                          {isCrossBorder ? '跨境' : '国内采购'}
                        </Badge>
                        <span className="truncate">{record.shop}</span>
                      </div>
                      <div className="text-xs text-muted-foreground mt-1">
                        {record.triggerInfo}
                      </div>
                      <div className="flex items-start gap-1.5 mt-2 text-xs text-muted-foreground">
                        <Lightbulb className="size-3.5 shrink-0 mt-0.5 text-amber-500" />
                        <span className="line-clamp-2">{record.suggestion}</span>
                      </div>
                      <div className="flex items-center gap-2 mt-2">
                        <Button
                          size="sm"
                          variant="ghost"
                          className="h-6 text-xs px-2"
                          onClick={() => onViewOrder?.(record)}
                        >
                          <Eye className="size-3 mr-1" />
                          查看详情
                        </Button>
                      </div>
                    </div>
                  </div>
                </div>
              );
            })}

            {hasMore && (
              <div className="flex justify-center pt-1">
                <Button variant="ghost" size="sm" onClick={() => setExpanded((e) => !e)}>
                  {expanded ? (
                    <>
                      收起
                      <ChevronUp className="size-4 ml-1" />
                    </>
                  ) : (
                    <>
                      展开更多（还有 {filteredRecords.length - LIST_COLLAPSE_THRESHOLD} 条）
                      <ChevronDown className="size-4 ml-1" />
                    </>
                  )}
                </Button>
              </div>
            )}
          </div>
        )}
      </CardContent>
    </Card>
  );
});
