// ========== 兼容映射 ==========
const PLATFORM_COMPAT_MAP: Record<string, PurchasePlatform> = {
  '1688': '国内1688',
  '淘宝': '国内淘宝',
  '拼多多': '国内PDD',
  'pdd': '国内PDD',
  'PDD': '国内PDD',
  '咸鱼': '国内闲鱼',
};

export function normalizePlatformForDisplay(platform: string): PurchasePlatform {
  const p = platform?.trim() || '';
  if (!p) return PURCHASE_PLATFORMS[2];
  if ((PURCHASE_PLATFORMS as readonly string[]).includes(p)) return p as PurchasePlatform;
  if (PLATFORM_COMPAT_MAP[p]) return PLATFORM_COMPAT_MAP[p];
  return p as PurchasePlatform;
}

export function normalizeShopForDisplay(shop: string): string {
  const trimmed = shop?.trim() || '';
  if (!trimmed) return trimmed;
  if (/^AMZ[\s／]/i.test(trimmed)) return trimmed;
  const amzMatch = trimmed.match(/^亚马逊(.+?)(站|店)?$/);
  if (amzMatch) {
    const site = amzMatch[1].trim();
    return `AMZ ${site}店`;
  }
  return trimmed;
}

// ========== ID 生成 ==========
export function genId(): string {
  return 'po_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 6);
}

// ========== 日期格式化 ==========
export function formatDate(date: string | Date | undefined | null): string {
  if (!date) return '—';
  const d = typeof date === 'string' ? new Date(date) : date;
  if (isNaN(d.getTime())) return '—';
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  const h = String(d.getHours()).padStart(2, '0');
  const min = String(d.getMinutes()).padStart(2, '0');
  return `${y}-${m}-${day} ${h}:${min}`;
}

// 取 YYYY-MM-DD 部分（兼容 ISO datetime 和 YYYY-MM-DD）
export function toDateStr(s: string): string {
  if (!s) return '';
  const d = new Date(s);
  if (isNaN(d.getTime())) return s.slice(0, 10);
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

// ========== 状态工具 ==========
export function getStatusMeta(status: OrderStatus) {
  return ORDER_STATUS.find((s) => s.key === status) || ORDER_STATUS[0];
}

export function getStatusIndex(status: OrderStatus): number {
  return ORDER_STATUS.findIndex((s) => s.key === status);
}

export function nextStatus(current: OrderStatus): OrderStatus | null {
  const idx = getStatusIndex(current);
  if (idx < 0 || idx >= ORDER_STATUS.length - 1) return null;
  return ORDER_STATUS[idx + 1].key;
}

// ========== 时效计算 ==========
export function calcLeadDays(orderedAt?: string, arrivedAt?: string): number | null {
  if (!orderedAt || !arrivedAt) return null;
  const start = new Date(orderedAt).getTime();
  const end = new Date(arrivedAt).getTime();
  if (isNaN(start) || isNaN(end)) return null;
  return Math.round((end - start) / (1000 * 60 * 60 * 24) * 10) / 10;
}

// ========== 时效趋势 ==========
export function getRecentDays(n: number): string[] {
  const result: string[] = [];
  const today = new Date();
  for (let i = n - 1; i >= 0; i--) {
    const d = new Date(today);
    d.setDate(today.getDate() - i);
    result.push(toDateStr(d.toISOString()));
  }
  return result;
}

export function calcLeadTimeTrend(records: LeadTimeRecord[], days: number): LeadTimeTrendItem[] {
  const dateList = getRecentDays(days);
  const arrivedRecords = records.filter((r) => r.arrivedAt);

  return dateList.map((date) => {
    const dayRecords = arrivedRecords.filter((r) => toDateStr(r.arrivedAt) === date);
    const count = dayRecords.length;
    if (count === 0) return { date, avgDays: null, count: 0 };
    const validRecords = dayRecords.filter((r) => r.orderedAt);
    if (validRecords.length === 0) return { date, avgDays: null, count };
    const totalDays = validRecords.reduce((sum, r) => {
      const d = calcLeadDays(r.orderedAt, r.arrivedAt);
      return sum + (d ?? 0);
    }, 0);
    return {
      date,
      avgDays: Math.round((totalDays / validRecords.length) * 10) / 10,
      count,
    };
  });
}

// ========== 时效建议 ==========
export function generateLeadTimeSuggestions(records: LeadTimeRecord[]): LeadTimeSuggestion[] {
  const suggestions: LeadTimeSuggestion[] = [];
  const arrivedRecords = records.filter((r) => r.arrivedAt);

  if (arrivedRecords.length === 0) return suggestions;

  const totalDays = arrivedRecords.reduce((sum, r) => {
    const d = calcLeadDays(r.orderedAt, r.arrivedAt);
    return sum + (d ?? 0);
  }, 0);
  const avgDays = Math.round((totalDays / arrivedRecords.length) * 10) / 10;

  if (avgDays > 15) {
    suggestions.push({
      type: 'warning',
      icon: 'trending-up',
      title: `平均时效偏长（${avgDays}天）`,
      content: '整体订单平均时效超过15天，建议关注物流商服务质量，考虑更换更快的物流渠道或货代；同时可与供应商协商缩短发货周期。',
    });
  } else if (avgDays > 7) {
    suggestions.push({
      type: 'info',
      icon: 'lightbulb',
      title: `平均时效 ${avgDays} 天`,
      content: '时效处于正常偏高水平，建议持续监控核心物流渠道表现，旺季前提前备货以应对可能的延误。',
    });
  } else {
    suggestions.push({
      type: 'success',
      icon: 'zap',
      title: `时效良好（平均${avgDays}天）`,
      content: '当前订单时效表现优秀，建议保持现有物流渠道和供应商合作，并可尝试将优秀渠道的经验复制到其他品类。',
    });
  }

  const platformMap = new Map<string, { total: number; days: number }>();
  arrivedRecords.forEach((r) => {
    const d = calcLeadDays(r.orderedAt, r.arrivedAt) ?? 0;
    const curr = platformMap.get(r.platform) ?? { total: 0, days: 0 };
    platformMap.set(r.platform, { total: curr.total + 1, days: curr.days + d });
  });

  let slowestPlatform = '';
  let slowestDays = 0;
  platformMap.forEach((v, k) => {
    const avg = v.days / v.total;
    if (avg > slowestDays && v.total >= 2) {
      slowestDays = avg;
      slowestPlatform = k;
    }
  });

  if (slowestPlatform && slowestDays > 10) {
    suggestions.push({
      type: 'warning',
      icon: 'target',
      title: `${slowestPlatform} 时效偏长`,
      content: `${slowestPlatform} 渠道平均时效约 ${Math.round(slowestDays * 10) / 10} 天，建议评估该平台供应商发货速度和物流渠道，考虑换用更高效的供应商或物流方式。`,
    });
  }

  const abnormalCount = records.filter(
    (r) => r.arrivalQuality === 'damaged' || r.arrivalQuality === 'defective' || r.arrivalQuality === 'missing',
  ).length;
  const abnormalRate = arrivedRecords.length > 0 ? abnormalCount / arrivedRecords.length : 0;

  if (abnormalRate > 0.2) {
    suggestions.push({
      type: 'warning',
      icon: 'trending-up',
      title: `异常率偏高（${Math.round(abnormalRate * 100)}%）`,
      content: `到货异常率超过20%（${abnormalCount}/${arrivedRecords.length}单），建议排查供应链各环节：供应商质检、包装质量、物流搬运等，针对性改进。`,
    });
  } else if (abnormalRate > 0.1) {
    suggestions.push({
      type: 'info',
      icon: 'lightbulb',
      title: `异常率 ${Math.round(abnormalRate * 100)}%，需关注`,
      content: '存在一定比例的到货异常，建议重点记录异常类型和原因，积累数据后针对性优化供应商或物流选择。',
    });
  }

  if (arrivedRecords.length >= 5 && avgDays > 10) {
    suggestions.push({
      type: 'info',
      icon: 'target',
      title: '建议提前备货',
      content: '考虑到整体时效较长，建议对热销产品提前15-20天下单备货，避免断货风险；同时可建立安全库存机制，应对物流波动。',
    });
  }

  return suggestions;
}

