 // ========== 采购单存取 ==========
export function loadOrders(): PurchaseOrder[] {
   try {
     const raw = scopedStorage.getItem(STORAGE_KEY);
      if (raw) {
        let data = JSON.parse(raw) as PurchaseOrder[];
        if (!Array.isArray(data)) return [];
        const now = new Date().toISOString();
        data = data.map((o: any) => ({
          ...o,
          // snake_case → camelCase 兼容（云同步拉回的字段）
          id: o.id,
          platform: o.platform,
          status: o.status || 'ordered',
          shop: o.shop || '',
          productName: o.productName || o.product_name || '未命名商品',
          quantity: o.quantity,
          amount: o.amount,
          carrier: o.carrier,
          trackingNumber: o.trackingNumber || o.tracking_number,
          trackingUrl: o.trackingUrl || o.tracking_url,
          remark: o.remark,
          arrivalQuality: o.arrivalQuality || o.arrival_quality,
          qualityNote: o.qualityNote || o.quality_note,
          createdAt: o.createdAt || o.created_at || o.updatedAt || o.updated_at || o.purchaseTime || now,
          updatedAt: o.updatedAt || o.updated_at || o.createdAt || o.created_at || o.purchaseTime || now,
          shippedAt: o.shippedAt || o.shipped_at,
          arrivedAt: o.arrivedAt || o.arrived_at,
          warehousedAt: o.warehousedAt || o.warehoused_at,
          purchaseTime: o.purchaseTime || o.purchase_date || o.purchaseDate,
          purchaseDate: o.purchaseDate || o.purchase_date,
          productUrl: o.productUrl,
          expressTimeline: o.expressTimeline,
        }));
        // 60天过期清理：只保留最近60天有活动的记录
        const cutoff = Date.now() - 60 * 24 * 60 * 60 * 1000;
        const beforeLen = data.length;
        data = data.filter((o) => {
          const t = new Date(o.updatedAt || o.createdAt || '').getTime();
          return !isNaN(t) ? t >= cutoff : true;
        });
        if (data.length !== beforeLen) {
          saveOrders(data);
          logger.info(`[loadOrders] 清理过期订单 ${beforeLen - data.length} 条，剩余 ${data.length} 条`);
        }
        return data.map((o) => ({
          ...o,
          shop: normalizeShopForDisplay(o.shop),
          platform: normalizePlatformForDisplay(o.platform),
        }));
     } else {
       // 首次启动：注入演示数据用于验证趋势图精确性
       const demo: PurchaseOrder[] = [
         {
           id: 'demo-1',
           platform: '国内1688',
           shop: '义乌优品旗舰店',
           productName: '【演示】硅胶冰格 10格',
           quantity: 10,
           amount: 89,
           status: 'warehoused',
           createdAt: '2026-10-10T10:00:00.000Z',
           updatedAt: '2026-10-15T16:30:00.000Z',
           purchaseTime: '2026-10-10T10:00:00.000Z',
           arrivedAt: '2026-10-15T16:30:00.000Z',
           trackingNumber: 'YT1234567890',
           arrivalQuality: 'normal',
         },
       ];
       scopedStorage.setItem(STORAGE_KEY, JSON.stringify(demo));
       return demo.map((o) => ({
         ...o,
         shop: normalizeShopForDisplay(o.shop),
         platform: normalizePlatformForDisplay(o.platform),
       }));
     }
   } catch (err) {
     logger.error('加载采购单失败:', String(err));
   }
   return [];
 }

