// 从时效记录推导状态
export function getLeadtimeStatus(r: LeadTimeRecord): OrderStatus {
  if (r.status) return r.status;
  if (r.arrivedAt) {
    return 'arrived';
  }
  if (r.trackingNumber) {
    const days = calcLeadDays(r.orderedAt, new Date().toISOString().slice(0, 10));
    if (days !== null && days > 3) return 'in_transit';
    return 'shipped';
  }
  return 'pending_ship';
}

// ========== 统计 ==========
export function computeStats(orders: PurchaseOrder[]) {
  const stats = {
    total: orders.length,
    inTransit: 0,
    arrived: 0,
    warehoused: 0,
    ordered: 0,
    pendingShip: 0,
    shipped: 0,
  };
  orders.forEach((o) => {
    if (o.status === 'in_transit') stats.inTransit++;
    if (o.status === 'arrived') stats.arrived++;
    if (o.status === 'warehoused') stats.warehoused++;
    if (o.status === 'ordered') stats.ordered++;
    if (o.status === 'pending_ship') stats.pendingShip++;
    if (o.status === 'shipped') stats.shipped++;
  });
  return stats;
}

// 本月采购总金额（按 createdAt / purchaseDate 归属自然月）
export function computeMonthlyAmount(orders: PurchaseOrder[]): number {
  const now = new Date();
  const y = now.getFullYear();
  const m = now.getMonth();
  let total = 0;
  orders.forEach((o) => {
    if (!o.amount) return;
    const dateStr = o.purchaseDate || o.purchaseTime || o.createdAt;
    if (!dateStr) return;
    const d = new Date(dateStr);
    if (isNaN(d.getTime())) return;
    if (d.getFullYear() === y && d.getMonth() === m) {
      total += o.amount;
    }
  });
  return Math.round(total * 100) / 100;
}

// ========== 运输天数计算 ==========
function getShippingDays(order: PurchaseOrder): number | null {
  const baseTime = order.shippedAt || order.updatedAt || order.createdAt;
  if (!baseTime) return null;
  const start = new Date(baseTime).getTime();
  const now = Date.now();
  const diffDays = (now - start) / (1000 * 60 * 60 * 24);
  return Math.floor(diffDays);
}

function extractExpectedDays(text: string): number | null {
  const match = text.match(/(\d+)\s*天/);
  if (match) return parseInt(match[1], 10);
  const rangeMatch = text.match(/(\d+)\s*[-~～]\s*(\d+)\s*天/);
  if (rangeMatch) return parseInt(rangeMatch[2], 10);
  return null;
}

 // ========== 异常检测（国内采购单） ==========
export function detectDomesticAbnormalRecords(orders: PurchaseOrder[]): AbnormalRecord[] {
  const results: AbnormalRecord[] = [];

  orders.forEach((order) => {
    // 运输超 7 天
    if (order.status === 'shipped' || order.status === 'in_transit') {
      const days = getShippingDays(order);
      const expectedDays = order.expressTimeline ? extractExpectedDays(order.expressTimeline) : null;
      const isOverdue = (days !== null && days > 7) || (expectedDays !== null && expectedDays > 7);
      if (isOverdue) {
        const info = days !== null ? `已运输 ${days} 天` : `预计时效 ${expectedDays} 天`;
        results.push({
          type: 'shipping_delay',
          source: 'domestic',
          order,
          productName: order.productName,
          shop: order.shop,
          days: days ?? expectedDays ?? undefined,
          triggerInfo: info,
          suggestion: ABNORMAL_SUGGESTIONS.shipping_delay,
        });
      }
    }

    // 到货质检异常：只要 arrivalQuality 非 normal 就算，不再卡订单状态
    // （用户可能在任何阶段先做质检登记）
    if (order.arrivalQuality && order.arrivalQuality !== 'normal') {
      const qualityMap = {
        damaged: { type: 'arrival_damaged' as const, label: '破损' },
        defective: { type: 'arrival_defective' as const, label: '瑕疵' },
        missing: { type: 'quantity_missing' as const, label: '漏件' },
        color_diff: { type: 'arrival_color_diff' as const, label: '到件色差' },
        accessory_missing: { type: 'arrival_accessory_missing' as const, label: '配件缺少' },
        wrong_item: { type: 'arrival_wrong_item' as const, label: '货不对版' },
        replacement: { type: 'arrival_replacement' as const, label: '补寄换货' },
      };
      const q = qualityMap[order.arrivalQuality];
      if (q) {
        results.push({
          type: q.type,
          source: 'domestic',
          order,
          productName: order.productName,
          shop: order.shop,
          triggerInfo: `到货质检：${q.label}`,
          suggestion: ABNORMAL_SUGGESTIONS[q.type],
        });
      }
    }
  });

  return results;
}

// ========== 异常检测（跨境时效记录） ==========
// 按运输天数分级：>20 / >25 / >30 / >35 各算一个异常等级（取最高级，不重复计入）
export function detectCrossBorderAbnormalRecords(records: LeadTimeRecord[]): AbnormalRecord[] {
  const results: AbnormalRecord[] = [];

  records.forEach((record) => {
    // 已到货/已入仓的不算运输延误异常
    if (record.status === 'arrived' || record.status === 'warehoused' || record.arrivedAt) return;

    const baseTime = record.orderedAt;
    if (!baseTime) return;
    const t = new Date(baseTime).getTime();
    if (isNaN(t)) return;
    const days = Math.floor((Date.now() - t) / (1000 * 60 * 60 * 24));

    let type: AbnormalType | null = null;
    if (days >= 35) {
      type = 'cross_border_35d';
    } else if (days >= 30) {
      type = 'cross_border_30d';
    } else if (days >= 25) {
      type = 'cross_border_25d';
    } else if (days >= 20) {
      type = 'cross_border_20d';
    }

    if (type) {
      results.push({
        type,
        source: 'cross_border',
        leadTimeRecord: record,
        productName: record.productName,
        shop: record.shop,
        days,
        triggerInfo: `跨境运输已 ${days} 天`,
        suggestion: ABNORMAL_SUGGESTIONS[type],
      });
    }

    // 跨境到货质检异常也并入
    if (record.arrivalQuality && record.arrivalQuality !== 'normal' && record.arrivedAt) {
      const qualityMap = {
        damaged: { type: 'arrival_damaged' as const, label: '破损' },
        defective: { type: 'arrival_defective' as const, label: '瑕疵' },
        missing: { type: 'quantity_missing' as const, label: '漏件' },
        color_diff: { type: 'arrival_color_diff' as const, label: '到件色差' },
        accessory_missing: { type: 'arrival_accessory_missing' as const, label: '配件缺少' },
        wrong_item: { type: 'arrival_wrong_item' as const, label: '货不对版' },
        replacement: { type: 'arrival_replacement' as const, label: '补寄换货' },
      };
      const q = qualityMap[record.arrivalQuality];
      if (q) {
        results.push({
          type: q.type,
          source: 'cross_border',
          leadTimeRecord: record,
          productName: record.productName,
          shop: record.shop,
          triggerInfo: `跨境到货质检：${q.label}`,
          suggestion: ABNORMAL_SUGGESTIONS[q.type],
        });
      }
    }
  });

  return results;
}

// ========== 统一异常统计 ==========
export function computeAbnormalStats(records: AbnormalRecord[]) {
  return {
    total: records.length,
    shippingDelay: records.filter((r) => r.type === 'shipping_delay').length,
    damaged: records.filter((r) => r.type === 'arrival_damaged').length,
    defective: records.filter((r) => r.type === 'arrival_defective').length,
    missing: records.filter((r) => r.type === 'quantity_missing').length,
    cross20d: records.filter((r) => r.type === 'cross_border_20d').length,
    cross25d: records.filter((r) => r.type === 'cross_border_25d').length,
    cross30d: records.filter((r) => r.type === 'cross_border_30d').length,
    cross35d: records.filter((r) => r.type === 'cross_border_35d').length,
    crossTotal: records.filter((r) => r.source === 'cross_border').length,
    domesticTotal: records.filter((r) => r.source === 'domestic').length,
  };
}

  // ========== 跨境订单预警分级 ==========
 // 运输超20天=注意(黄) / 25天=警告(橙) / 30天=严重(红) / 35天=异常(深红)
 export function getCrossBorderAlert(order: CrossBorderOrder): CrossBorderAlert | null {
   // 已到货/已入仓 → 无预警
   if (order.status === 'arrived' || order.status === 'warehoused' || order.arrivedAt) {
     return null;
   }
   // 取基准时间：已发货用 shippedAt，否则用 orderedAt
   const baseTime = order.shippedAt || order.orderedAt;
   if (!baseTime) return null;
   const t = new Date(baseTime).getTime();
   if (isNaN(t)) return null;
   const days = Math.floor((Date.now() - t) / (1000 * 60 * 60 * 24));

   if (days >= 35) {
     return {
       level: 'critical',
       label: '严重异常',
       color: 'bg-red-700',
       textColor: 'text-red-700',
       message: `超${days}天，严重运输异常，疑似丢件，请立即处理`,
       days,
     };
   }
   if (days >= 30) {
     return {
       level: 'severe',
       label: '严重',
       color: 'bg-red-500',
       textColor: 'text-red-600',
       message: `超${days}天，请货代尽快处理，防止丢件`,
       days,
     };
   }
   if (days >= 25) {
     return {
       level: 'warning',
       label: '警告',
       color: 'bg-orange-500',
       textColor: 'text-orange-600',
       message: `超${days}天，请联系货代并催促尾端派送`,
       days,
     };
   }
   if (days >= 20) {
     return {
       level: 'attention',
       label: '注意',
       color: 'bg-amber-500',
       textColor: 'text-amber-600',
       message: `运输已达${days}天，请关注`,
       days,
     };
   }
   return null;
 }

 // 跨境订单统计
 export function calcCrossBorderStats(orders: CrossBorderOrder[]) {
   const stats = {
     total: orders.length,
     inTransit: 0,
     arrived: 0,
     warehoused: 0,
     abnormal: 0,
     attention: 0,
     warning: 0,
     severe: 0,
     critical: 0,
   };
   orders.forEach((o) => {
     if (o.status === 'in_transit' || o.status === 'shipped') stats.inTransit++;
     if (o.status === 'arrived') stats.arrived++;
     if (o.status === 'warehoused') stats.warehoused++;
     const alert = getCrossBorderAlert(o);
     if (alert) {
       if (alert.level === 'attention') stats.attention++;
       if (alert.level === 'warning') stats.warning++;
       if (alert.level === 'severe') stats.severe++;
       if (alert.level === 'critical') stats.critical++;
       if (alert.level === 'severe' || alert.level === 'critical') stats.abnormal++;
     }
     if (o.status === 'arrived' || o.status === 'warehoused') return;
   });
   return stats;
 }
