import { useState, useCallback, useEffect } from 'react';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Badge } from '@/components/ui/badge';
import { ScrollArea } from '@/components/ui/scroll-area';
import { Separator } from '@/components/ui/separator';
import { Loader2, Truck, Package, CheckCircle, AlertCircle, ChevronRight } from 'lucide-react';
import { toast } from 'sonner';
import { logger } from '@lark-apaas/client-toolkit-lite';
import { cn } from '@/lib/utils';
import { KUAIDI100_API_KEY, COMMON_CARRIERS } from './types';

interface LogisticsDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  trackingNumber: string;
  carrierName?: string;
  apiKey: string;
}

interface LogisticsEvent {
  time: string;
  context: string;
  location?: string;
  status?: string;
}

interface AutoCarrierResult {
  com: string;
  name: string;
}

export default function LogisticsDialog({
  open,
  onOpenChange,
  trackingNumber,
  carrierName,
  apiKey,
}: LogisticsDialogProps) {
  const [events, setEvents] = useState<LogisticsEvent[]>([]);
  const [loading, setLoading] = useState(false);
  const [autoList, setAutoList] = useState<AutoCarrierResult[]>([]);
  const [showManualSelect, setShowManualSelect] = useState(false);
  const [currentCarrier, setCurrentCarrier] = useState('');
  const [currentCarrierCode, setCurrentCarrierCode] = useState('');
  const [inputNumber, setInputNumber] = useState(trackingNumber);

  useEffect(() => {
    if (open) {
      setInputNumber(trackingNumber);
      setEvents([]);
      setAutoList([]);
      setShowManualSelect(false);
      setCurrentCarrier(carrierName || '');
      setCurrentCarrierCode('');
      if (trackingNumber) {
        // 自动查询
        handleQuery(trackingNumber);
      }
    }
  }, [open, trackingNumber, carrierName]);

  const handleQuery = useCallback(
    async (number: string, carrierCode?: string, carrierLabel?: string) => {
      if (!number.trim()) {
        toast.error('请输入运单号');
        return;
      }

      setLoading(true);
      setEvents([]);

      try {
        const key = apiKey || KUAIDI100_API_KEY;
        let com = carrierCode || '';
        let carrierName = carrierLabel || '';

        // 没有传 carrierCode 时自动识别
        if (!com) {
          try {
            const autoRes = await fetch(
              `https://www.kuaidi100.com/autonumber/autoComNum?resultv2=1&text=${encodeURIComponent(number)}&key=${encodeURIComponent(key)}`,
            );
            if (autoRes.ok) {
              const autoData = await autoRes.json();
              const auto: { comCode?: string; com?: string; type?: string; name?: string }[] =
                autoData?.auto || autoData?.result || [];
              const list = auto
                .map((a) => ({
                  com: a.comCode || a.com || a.type || '',
                  name: a.name || a.comCode || a.com || a.type || '',
                }))
                .filter((a) => a.com);
              setAutoList(list);
              if (list.length > 0) {
                com = list[0].com;
                carrierName = list[0].name;
              }
            }
          } catch {
            /* ignore auto detect error */
          }
        }

        if (com) {
          setCurrentCarrier(carrierName || com);
          setCurrentCarrierCode(com);
          const queryUrl = `https://www.kuaidi100.com/query?type=${encodeURIComponent(com)}&postid=${encodeURIComponent(number)}&temp=${Math.random()}&phone=&key=${encodeURIComponent(key)}`;
          const res = await fetch(queryUrl);
          if (res.ok) {
            const data = await res.json();
            if (data && (data.status === '200' || (data.data && Array.isArray(data.data) && data.data.length > 0))) {
              const list: LogisticsEvent[] = (data.data || []).map((item: any) => ({
                time: item.time || item.ftime || '',
                context: item.context || item.desc || '',
                location: item.location,
                status: item.status,
              }));
              setEvents(list);
              setShowManualSelect(false);
              return;
            }
            if (data?.message) {
              toast.error(data.message);
            } else {
              toast.error('查询失败，请检查运单号或快递公司');
            }
          } else {
            toast.error('物流查询请求失败');
          }
        } else {
          // 无法自动识别，显示手动选择
          setShowManualSelect(true);
          toast.info('未能自动识别快递公司，请手动选择');
        }
      } catch (err) {
        logger.error('物流查询失败:', String(err));
        toast.error('查询失败，请稍后重试或检查网络');
      } finally {
        setLoading(false);
      }
    },
    [apiKey],
  );

  function handleManualSelect(code: string, name: string) {
    setCurrentCarrier(name);
    setCurrentCarrierCode(code);
    setShowManualSelect(false);
    handleQuery(inputNumber, code, name);
  }

  const latestEvent = events[0];
  const isDelivered = events.some((e) => e.context.includes('签收') || e.context.includes('已签收'));

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-md max-h-[85vh] flex flex-col p-0">
        <DialogHeader className="px-6 pt-6 pb-3 shrink-0">
          <DialogTitle className="flex items-center gap-2">
            <Truck className="size-5 text-primary" />
            物流查询
          </DialogTitle>
        </DialogHeader>

        <div className="px-6 space-y-3 shrink-0">
          <div className="flex items-center gap-2">
            <div className="flex-1">
              <Input
                value={inputNumber}
                onChange={(e) => setInputNumber(e.target.value)}
                placeholder="输入运单号"
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleQuery(inputNumber);
                }}
              />
            </div>
            <Button onClick={() => handleQuery(inputNumber)} disabled={loading}>
              {loading ? <Loader2 className="size-4 animate-spin" /> : '查询'}
            </Button>
          </div>

          {currentCarrier && (
            <div className="flex items-center justify-between">
              <div className="text-sm text-muted-foreground">
                快递公司：<span className="text-foreground font-medium">{currentCarrier}</span>
              </div>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 text-xs text-primary"
                onClick={() => setShowManualSelect(!showManualSelect)}
              >
                切换快递公司
                <ChevronRight className="size-3 ml-1" />
              </Button>
            </div>
          )}

          {showManualSelect && (
            <div className="p-3 rounded-lg bg-muted/30 border border-border/40 space-y-2">
              {autoList.length > 0 && (
                <div>
                  <div className="text-xs text-muted-foreground mb-1.5">自动识别结果</div>
                  <div className="flex flex-wrap gap-1.5">
                    {autoList.map((c) => (
                      <Badge
                        key={c.com}
                        variant="outline"
                        className="cursor-pointer hover:bg-accent"
                        onClick={() => handleManualSelect(c.com, c.name)}
                      >
                        {c.name || c.com}
                      </Badge>
                    ))}
                  </div>
                </div>
              )}
              <div>
                <div className="text-xs text-muted-foreground mb-1.5">常用快递</div>
                <div className="flex flex-wrap gap-1.5">
                  {COMMON_CARRIERS.slice(0, 12).map((c) => (
                    <Badge
                      key={c.code}
                      variant="outline"
                      className="cursor-pointer hover:bg-accent"
                      onClick={() => handleManualSelect(c.code, c.name)}
                    >
                      {c.name}
                    </Badge>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        <Separator className="my-3 shrink-0" />

        {/* 物流轨迹 */}
        <ScrollArea className="flex-1 px-6">
          {loading && events.length === 0 ? (
            <div className="flex flex-col items-center justify-center py-16">
              <Loader2 className="size-8 animate-spin text-primary mb-3" />
              <p className="text-sm text-muted-foreground">正在查询物流信息...</p>
            </div>
          ) : events.length > 0 ? (
            <div className="relative pl-5 pb-4">
              <div className="absolute left-[7px] top-1 bottom-0 w-px bg-border" />
              {events.map((event, i) => {
                const isFirst = i === 0;
                const Icon = isFirst
                  ? isDelivered
                    ? CheckCircle
                    : Package
                  : Package;
                return (
                  <div key={i} className="relative pb-5 last:pb-0">
                    <div
                      className={cn(
                        'absolute -left-5 top-0.5 size-3.5 rounded-full border-2 border-background',
                        isFirst ? 'bg-primary' : 'bg-border',
                      )}
                    />
                    <div className="space-y-1">
                      <div
                        className={cn(
                          'text-sm leading-relaxed',
                          isFirst ? 'text-foreground font-medium' : 'text-muted-foreground',
                        )}
                      >
                        {event.context}
                      </div>
                      <div className="text-xs text-muted-foreground/70">{event.time}</div>
                    </div>
                  </div>
                );
              })}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-16 text-center">
              <AlertCircle className="size-10 text-muted-foreground/30 mb-3" />
              <p className="text-sm text-muted-foreground">暂无物流信息</p>
            </div>
          )}
        </ScrollArea>

        <DialogFooter className="px-6 py-4 border-t border-border/50 shrink-0">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            关闭
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
